var LESSONS = LESSONS || [];
LESSONS.push(
{
  "provenance": ["Số liệu trong sự cố, dòng thời gian và cách làm ngây thơ là giả định để dựng kịch bản, không phải số đo từ một hệ thống thật.","Các khẳng định về mã trạng thái HTTP, về preflight CORS và về cách một thư viện HTTP phía trình duyệt phân loại response được đối chiếu với tài liệu chính thức trong refs; phần còn lại là mô hình suy ra từ chúng."],
  "id": "L18",
  "stage": 4,
  "stageTitle": "Chặng 4 — Nối hai mảng",
  "stageIntro": "<p>Chặng này ghép hai mảng yếu của bạn vào một đường đi duy nhất: một lần bấm trên trình duyệt đi qua hợp đồng API, qua lớp xác thực, qua tệp trên S3, qua hàng đợi, rồi tới cơ sở dữ liệu và bản deploy. Không có cú pháp mới; mỗi bài thêm đúng một khớp nối và chỉ ra chỗ khớp đó vỡ khi tải cao, khi mạng chập chờn, hoặc khi hai lần deploy chồng lên nhau.</p>",
  "title": "Hợp đồng API giữa Vue và FastAPI",
  "goal": "Trong bài này bạn phải vẽ lại được đường đi của một response từ FastAPI tới Vue và chỉ đúng ba chỗ: nơi máy đọc kết quả, nơi người đọc chi tiết, và nơi cả hai được sinh ra; sau đó chọn đúng mã cho ba tình huống — dữ liệu sai hình dạng, SKU bị chặn, tạo mới thành công — và giải thích vì sao đổi một trường trong body mà không đổi mã lại làm vỡ client cũ.",
  "bridge": "Bạn đã biết chặn double submit bằng Idempotency-Key và biết một handler async chạy ở đâu; giờ hai thứ đó phải nằm trong một hợp đồng mà cả hai đầu đọc giống nhau, để kết quả nghiệp vụ không còn phải đoán từ một chuỗi thông báo trong body.",
  "buildsOn": ["L07","L17"],
  "incident": "<p>Giả sử tuần thứ hai của bản pilot, 100 nhân viên nội bộ thử tính năng đặt hàng. Một buổi chiều, đội hỗ trợ nhận 37 ticket giống nhau: người dùng bấm Đặt hàng, toast xanh báo thành công, nhưng đơn không có trong danh sách.</p><p>Log phía trình duyệt sạch. Log của FastAPI cho thấy cả 37 request bị từ chối vì SKU nằm trong danh sách chặn, nhưng server vẫn trả <code>200</code> kèm trường <code>error</code> trong body. Dashboard lỗi không nhích một điểm, vì mọi tầng đều đọc status code và thấy 200.</p><p>Giả sử sáng hôm sau backend thêm một trường bắt buộc vào body mà phía Vue không đổi gì. Từ 9 giờ, mọi POST dừng trước khi chạm server: header <code>Idempotency-Key</code> không có trong <code>Access-Control-Allow-Headers</code>, nên trình duyệt chặn ở bước preflight. Log FastAPI trống hoàn toàn.</p><p>Không ai viết sai cú pháp. Sai ở chỗ hai đầu dùng hai hợp đồng khác nhau cho cùng một API: một bên đọc body, một bên đọc mã, và không có gì kiểm được sự lệch đó trước khi người dùng gặp nó.</p>",
  "askFirst": ["Nếu cả hai đầu đều tin request đã thành công, dấu hiệu nào trong response đã bị bỏ qua?","Khi toast báo thành công mà bản ghi không tồn tại, tầng nào quyết định sai và nó dựa vào dữ liệu gì?","Muốn hai đầu không lệch nhau khi một trường mới xuất hiện, thứ gì phải được sinh ra từ cùng một nguồn?"],
  "predict": {"q":"Một route trả 409 kèm envelope {code, message, correlation_id}. Phía Vue có hai interceptor: A kiểm err.response.status === 409, B đọc err.response.data.error. Nếu backend đổi sang trả 200 kèm {error: \"sku bị chặn\"}, mỗi interceptor có chạy không, và cái nào còn đúng?","a":"<p>Với 409 và envelope hiện tại: A chạy vì status khớp; B không chạy vì envelope không có trường <code>error</code>, nên <code>data.error</code> là undefined. Với 200 kèm <code>{error}</code>: A không chạy vì status không khớp 409, và B cũng không chạy vì B chỉ được gắn vào nhánh lỗi — response 2xx không đi vào nhánh đó. Kết quả là cả hai im lặng, giao diện coi như thành công, đúng như sự cố trong bài. Kết luận: sau khi envelope đổi, chỉ A còn đúng, vì nó đọc kết quả từ status; B phụ thuộc tên trường nên vỡ mỗi lần envelope đổi tên.</p>"},
  "naive": "<p>Cách làm ngây thơ là coi body là nơi chứa kết quả, còn status code là chi tiết trang trí.</p><ul><li><strong>Niềm tin:</strong> route nào cũng trả <code>200</code> rồi nhét <code>ok: false</code> vào body, vì client chỉ cần đọc một trường là biết kết quả.</li><li><strong>Vì sao nghe hợp lý:</strong> khi chỉ có một client do chính bạn viết, bạn luôn nhớ đọc trường đó, và mọi lần thử tay đều xanh.</li><li><strong>Chỗ chết:</strong> những tầng bạn không viết — thư viện HTTP, cache, gateway, log, alert — chỉ đọc mã. Chúng thấy 200 và cho qua, còn trường <code>ok</code> thì không tầng nào đọc.</li></ul>",
  "naiveCode": "# ❌ Mọi route trả 200; kết quả thật nằm trong body.\nfrom itertools import count\n\nfrom fastapi import FastAPI\nfrom pydantic import BaseModel\n\napp = FastAPI()\nBANNED_SKUS = {\"banned-sku\"}\n_ids = count(1)\n\n\nclass CreateOrder(BaseModel):\n    sku: str\n    qty: int\n\n\n@app.post(\"/orders\")\nasync def create_order(body: CreateOrder):\n    if body.sku in BANNED_SKUS:\n        # Không có mã lỗi nào: FastAPI trả 200 OK.\n        return {\"ok\": False, \"error\": \"sku đang bị chặn\"}\n    # Không khai response_model: dict trả nguyên vẹn, kể cả trường nội bộ.\n    return {\"ok\": True, \"order\": {\"id\": next(_ids), \"internal_note\": \"chờ kế toán duyệt\"}}",
  "naiveOut": "Gọi POST /orders với sku=banned-sku: server trả 200 kèm body báo lỗi. Phía Vue, lời gọi không ném exception nên state chuyển sang xong và toast xanh hiện ra. Access log của FastAPI cũng ghi 200, nên tỉ lệ lỗi trên dashboard không nhích. Ở nhánh thành công, response còn mang internal_note — trường nội bộ lẽ ra không được ra ngoài. Không có exception nào ở bất kỳ đâu; chỉ có một quyết định thiết kế sai được lặp lại ở mọi route.",
  "timeline": [["14:02:11","Bản pilot mở cho 100 người dùng nội bộ; POST /orders chạy ổn định với p99 giả định 180 ms."],["14:05:30","Danh sách SKU bị chặn được bật; 37 người dùng có mã nằm trong danh sách đó."],["14:05:31","Cả 37 request trả 200 kèm trường error trong body; không request nào trả 4xx."],["14:05:32","Phía Vue nhận 200 nên chạy nhánh thành công và hiện toast xanh cho cả 37 người."],["14:20:00","Hỗ trợ bắt đầu nhận ticket; access log của FastAPI toàn 200 nên không ai thấy lỗi."],["Hôm sau 09:01","Trình duyệt chặn ở preflight vì Idempotency-Key thiếu trong allow-headers; log server trống."]],
  "rootCause": "<p>Ba mắt xích nối tiếp nhau.</p><ol><li>Kết quả nghiệp vụ bị mã hoá vào body, nên <code>200</code> không còn nghĩa là thành công — nó chỉ có nghĩa là server đã trả lời.</li><li>Vì status không mang kết quả, mỗi client phải tự học một quy ước riêng, và quy ước đó không nằm trong bất kỳ thứ gì máy kiểm được.</li><li>Vì không có gì máy kiểm được, thay đổi hình dạng request chỉ lộ ra qua lỗi runtime: trình duyệt chặn preflight trước khi request chạm server, nên log phía server không có gì để tra.</li></ol>",
  "concept": "Status code là kết quả dành cho máy, body là chi tiết dành cho người; một hợp đồng API chỉ đúng khi cả hai kênh được sinh ra từ cùng một schema, và mọi client đọc kết quả từ status chứ không đoán theo tên trường trong JSON.",
  "mechanism": "<ol><li><strong>Vue gửi request qua một client dùng chung:</strong> interceptor gắn <code>Authorization</code> và <code>Idempotency-Key</code>, payload dùng đúng tên trường trong schema, không component nào tự gọi <code>fetch</code> riêng.</li><li><strong>Pydantic chặn ở biên vào:</strong> thiếu trường hoặc sai kiểu thì FastAPI dừng trước handler với <code>422</code> kèm danh sách lỗi từng trường, nên handler và cơ sở dữ liệu không bao giờ thấy dữ liệu bẩn.</li><li><strong>Handler quyết định kết quả bằng mã:</strong> tạo mới trả <code>201</code> kèm <code>Location</code>, SKU bị chặn trả <code>409</code>, thiếu quyền trả <code>403</code>; mọi lỗi đi qua một exception handler chung nên envelope có cùng hình dạng.</li><li><strong>response_model lọc chiều ra:</strong> FastAPI cắt mọi trường không khai báo, nên ghi chú nội bộ không lọt ra ngoài; cùng các model đó sinh ra <code>openapi.json</code>.</li><li><strong>CI sinh client từ openapi.json:</strong> phía Vue typecheck theo kiểu vừa sinh, nên lệch tên trường đỏ ngay lúc build thay vì hiện <code>undefined</code> trên production.</li></ol>",
  "visuals": [{"id": "flow-api-contract", "question": "Một response đi qua những trạm nào, và trạm nào đọc kết quả thành công hay thất bại?", "focus": "Status code"}],
  "failureModes": "<p>Hợp đồng chặt cũng tạo ra bốn kiểu hỏng mới.</p><ul><li><strong>Thêm trường bắt buộc.</strong> Niềm tin sai: thêm một trường là thay đổi nhỏ. Nghe hợp lý vì server tự tin nó đúng. Điều đúng: trường mới phải có giá trị mặc định, hoặc đi hai giai đoạn — server chấp nhận cả thiếu lẫn có, rồi mới siết. Phản chứng: ngay sau deploy, log đầy <code>422</code> với <code>missing</code> ở đúng trường mới, từ những client chưa cập nhật.</li><li><strong>Trả thẳng dict nội bộ.</strong> Niềm tin sai: trả gì cũng được, client chỉ đọc trường nó cần. Nghe hợp lý vì test tay vẫn qua. Điều đúng: phải có <code>response_model</code> làm màng lọc đầu ra. Phản chứng: response chứa <code>internal_note</code>, và lần sau đổi tên trường đó lại thành thay đổi hợp đồng ngoài ý muốn.</li><li><strong>Envelope không nhất quán.</strong> Niềm tin sai: route nào có nhánh lỗi là đủ. Nghe hợp lý vì mỗi route đều xử lý lỗi của nó. Điều đúng: hình dạng lỗi phải giống nhau ở mọi route. Phản chứng: interceptor phải rẽ nhánh theo URL, và nhánh nào cũng có thể sai mà không ai thấy.</li><li><strong>Không kiểm hợp đồng trong CI.</strong> Niềm tin sai: đổi tên trường là việc riêng của backend. Nghe hợp lý vì code vẫn chạy. Điều đúng: client phải được sinh và typecheck từ schema. Phản chứng: màn hình hiện <code>undefined</code> hoặc <code>NaN</code> ngay sau deploy, còn log server không có một lỗi nào.</li></ul>",
  "tradeoff": "<p><strong>Cái được.</strong> Kết quả thành bại nằm ở đúng một kênh máy đọc, nên cache, gateway, log và alert xử lý đúng mà không cần hiểu nghiệp vụ; lệch schema bị chặn ở CI thay vì ở người dùng, và trường nội bộ không thể lọt ra ngoài vì màng lọc là khai báo chứ không phải kỷ luật của người viết.</p><p><strong>Cái mất.</strong> Mỗi trường mới phải trả lời ba câu: bắt buộc hay tuỳ chọn, có lộ ra ngoài không, client cũ có chịu được không. Pipeline phía client đỏ khi schema đổi, nên hai đội phải phối hợp trước mỗi lần deploy — chậm hơn hẳn so với trả một dict tự do. Với một prototype một người làm cả hai đầu, chi phí này lớn hơn lợi ích, và trả dict tự do là lựa chọn hợp lý.</p><p><strong>Khi nào xứng đáng.</strong> Từ hai client trở lên, hoặc khi đã có người dùng thật: một lần deploy sai hợp đồng tốn nhiều hơn một buổi chiều viết schema. Dưới ngưỡng đó, chi phí bảo trì hợp đồng lớn hơn thiệt hại nó ngăn được.</p>",
  "alternatives": "<p><strong>Khi nào chọn cách khác.</strong></p><ul><li><strong>GraphQL.</strong> Chọn khi client cần tự chọn trường và gộp nhiều resource trong một lần gọi. Cái giá: lỗi vẫn nằm trong response <code>200</code> kèm mảng <code>errors</code> — đúng thứ bài này khuyên tránh — và cache, phân trang, giới hạn độ sâu đều phải tự quy ước.</li><li><strong>gRPC.</strong> Chọn cho service nội bộ cần hợp đồng chặt và sinh client tự động từ file <code>.proto</code>. Cái giá: trình duyệt không gọi thẳng được nên phải có proxy, và mã lỗi nằm trong trường status của message chứ không phải mã HTTP.</li><li><strong>REST + OpenAPI.</strong> Mặc định cho đội nhỏ, một backend nhiều client. Chi phí thấp nhất vì FastAPI sinh schema sẵn và mọi tầng trung gian đều hiểu HTTP; đây là lựa chọn của bài này.</li><li><strong>Không dùng schema.</strong> Chỉ hợp lý cho webhook nội bộ một chiều, nơi không ai đọc lại body và không có client thứ hai. Ngay khi có client thứ hai, nên chuyển sang REST + OpenAPI thay vì viết tài liệu tay.</li></ul>",
  "observe": "<p><strong>Bốn tín hiệu cho biết hợp đồng đã lệch.</strong></p><ul><li><strong>Phân bố status theo route.</strong> Một route chỉ toàn <code>2xx</code> trong khi nghiệp vụ chắc chắn có từ chối là dấu hiệu kết quả đang nằm trong body. Đọc từ access log hoặc metric của gateway, tách theo từng route.</li><li><strong>Lỗi preflight.</strong> Sau mỗi lần thêm header, gọi một <code>OPTIONS</code> thật. Nếu bỏ qua, lỗi CORS chỉ hiện ở trình duyệt người dùng và không để lại dòng log nào phía server.</li><li><strong>Correlation id.</strong> Mỗi lỗi trả về client phải tra được trong log. Nếu người dùng báo lỗi mà bạn không tìm ra dòng log tương ứng, envelope đang thiếu mảnh nối cuối cùng.</li><li><strong>Diff schema giữa hai bản deploy.</strong> So <code>openapi.json</code> của bản mới với bản trước; một trường bắt buộc mới xuất hiện mà không có ghi chú là thay đổi phá vỡ tương thích, và nó phải bị chặn trước khi phát hành.</li></ul>",
  "attacks": [{"q":"Vì sao phải tách 422 và 409 thay vì trả 400 cho mọi lỗi phía client?","a":"<p><strong>Kết luận:</strong> mỗi mã là một chỉ thị cho interceptor, và ba mã này dẫn tới ba hành vi giao diện khác nhau, nên gộp lại là mất thông tin.</p><ul><li><code>422</code>: đúng cú pháp JSON nhưng sai ràng buộc từng trường, nên giao diện chiếu mảng <code>details</code> vào đúng ô nhập và người dùng sửa được tại chỗ.</li><li><code>409</code>: đúng hình dạng nhưng xung đột trạng thái nghiệp vụ, ví dụ SKU vừa bị chặn hoặc đơn đã được duyệt trước một giây; sửa ô nhập vô ích, giao diện phải tải lại trạng thái mới nhất.</li><li><code>400</code>: gói tin hỏng ở mức giao thức, JSON cắt cụt hoặc thiếu header; đây là lỗi tích hợp, người dùng không làm gì được.</li></ul><p><strong>Điều kiện:</strong> cách tách này chỉ có lợi khi client đọc mã để chọn nhánh. Nếu client chỉ hiện một câu thông báo chung, gộp mã không mất gì. <strong>Dấu hiệu kiểm chứng:</strong> trong access log, một route chỉ có <code>4xx</code> chung chung và không phân biệt được hai nhóm trên là dấu hiệu client đang phải đoán từ chuỗi message.</p>"},{"q":"Một SKU vừa bị chặn vừa vượt tồn kho — bạn trả mã nào, envelope ghi gì, và giao diện làm gì?","a":"<p><strong>Kết luận:</strong> chọn một mã theo lý do chặn chính, và ghi các lý do còn lại vào <code>details</code>; đừng trả hai mã cho một response.</p><p>Thứ tự kiểm quyết định mã: nếu SKU nằm trong danh sách chặn thì <code>409</code> kèm <code>code: \"SKU_BLOCKED\"</code>, vì đây là xung đột nghiệp vụ không sửa được bằng cách đổi số lượng. Nếu SKU hợp lệ nhưng tồn kho không đủ thì vẫn <code>409</code> với <code>code: \"OUT_OF_STOCK\"</code> và <code>details: [{field: \"qty\", available: 3}]</code>. <code>422</code> chỉ dành cho trường hợp <code>qty</code> sai kiểu hoặc nhỏ hơn 1, tức là lỗi hình dạng.</p><p><strong>Điều kiện:</strong> nếu tồn kho là dữ liệu có thể đổi trong vài giây, đừng trả <code>409</code> như chân lý cuối — giao diện nên tải lại số lượng khả dụng. <strong>Dấu hiệu kiểm chứng:</strong> envelope phải có <code>correlation_id</code> tra được trong log, và <code>code</code> phải là hằng chuỗi mà phía Vue rẽ nhánh được, không phải câu tiếng Việt.</p>"},{"q":"Nếu client thứ hai là app mobile đã phát hành và không thể cập nhật, bạn đổi schema theo trình tự nào?","a":"<p><strong>Kết luận:</strong> mở rộng trước, thu hẹp sau, và chỉ thu hẹp khi log chứng minh không còn ai dùng trường cũ.</p><ol><li><strong>Mở rộng:</strong> thêm trường mới vào <code>response_model</code> và vẫn trả trường cũ; mọi trường mới ở đầu vào phải có giá trị mặc định để request cũ vẫn qua <code>422</code>.</li><li><strong>Chuyển:</strong> client mới đọc trường mới; client cũ tiếp tục đọc trường cũ mà không biết gì đã đổi.</li><li><strong>Thu hẹp:</strong> sau khi metric xác nhận không còn request nào dùng trường cũ trong một chu kỳ đủ dài, mới xoá nó ở một lần phát hành riêng.</li></ol><p><strong>Điều kiện:</strong> app mobile có người dùng không bao giờ cập nhật, nên cửa sổ chuyển phải tính bằng nhiều tháng, không phải vài ngày. <strong>Dấu hiệu kiểm chứng:</strong> diff <code>openapi.json</code> giữa hai bản phải chỉ có thêm trường, không có trường bắt buộc mới và không có trường bị xoá đột ngột.</p>"},{"q":"OpenAPI có bảo đảm hai đầu không lệch không, và nó không kiểm được điều gì?","a":"<p><strong>Kết luận:</strong> không. OpenAPI mô tả hình dạng, nên nó chỉ bắt được lệch hình dạng, và chỉ khi client thật sự được sinh từ nó.</p><ul><li>Nó không kiểm quyền: một endpoint khai đúng schema vẫn có thể trả dữ liệu của tenant khác nếu handler không lọc theo danh tính lấy từ token.</li><li>Nó không kiểm ngữ nghĩa: <code>200</code> với <code>items</code> rỗng và <code>200</code> với <code>items</code> bị cắt trang đều hợp lệ theo schema, nhưng khác nhau hoàn toàn với người đọc dữ liệu.</li><li>Nó không kiểm hành vi theo thời gian: schema không nói gì về việc một trường chỉ có sau khi job nền chạy xong.</li></ul><p><strong>Điều kiện:</strong> nếu client được viết tay thay vì sinh từ <code>openapi.json</code>, giá trị bắt lỗi gần như bằng không. <strong>Dấu hiệu kiểm chứng:</strong> một thay đổi schema đi qua CI mà không làm đỏ bước typecheck phía client nghĩa là bước đó chưa thật sự dùng schema.</p>"}],
  "anchor": "Status code là kết quả cho máy, body là chi tiết cho người, và cả hai phải sinh ra từ cùng một schema.",
  "say30": "Hợp đồng API là định nghĩa máy kiểm được về request, response và mã lỗi. Trong FastAPI nó nằm trong model Pydantic, và framework sinh OpenAPI từ chính model đó. Kết quả nghiệp vụ phải đi bằng status code, vì thư viện HTTP, cache và alert đều đọc mã; trả 200 kèm error trong body làm mọi tầng mù. Tôi trả 422 khi dữ liệu sai hình dạng, 409 khi xung đột nghiệp vụ, và gom mọi lỗi vào một envelope có correlation id.",
  "say90": "[Nêu vấn đề (30s)]: Hai đội viết hai đầu của một API bằng hai hợp đồng khác nhau. Backend trả 200 kèm trường error trong body, nên toast báo thành công trong khi đơn đã bị chặn, và dashboard lỗi không nhích vì mọi dòng log đều 200. Sáng hôm sau backend thêm một trường bắt buộc, trình duyệt chặn preflight, log server trống.\n\n[Cơ chế (45s)]: Tôi tách hai kênh. Status code là kết quả cho máy: 201 cho tạo mới kèm Location, 422 khi Pydantic chặn dữ liệu sai hình dạng, 409 khi SKU bị chặn, 403 khi thiếu quyền. Body là chi tiết cho người, gom vào một envelope có code, message và correlation_id từ một exception handler chung. Chiều ra đi qua response_model nên trường nội bộ không lọt. Cả hai kênh sinh từ cùng model Pydantic, nên openapi.json không lạc hậu và CI sinh client TypeScript để typecheck phía Vue.\n\n[Ranh giới (15s)]: Hợp đồng mô tả hình dạng chứ không phải phân quyền; quyền vẫn kiểm từng request ở backend. Và schema chặt vẫn phá client cũ nếu thêm trường bắt buộc, nên phải có giá trị mặc định.",
  "body": "<p><strong>Ví dụ chuyển giao.</strong> Một endpoint <code>GET /orders</code> trả mảng đơn, và một script đối soát nội bộ đọc mảng đó mỗi đêm. Khi danh sách vượt 5.000 đơn, backend đổi sang phân trang: body thành <code>{items, next_cursor}</code>, vẫn trả <code>200</code>.</p><p>Với status code, không có gì đổi: script vẫn nhận 200 và vẫn coi là thành công, nhưng <code>items</code> giờ chỉ còn 100 phần tử, nên đêm đó đối soát thiếu 4.900 đơn mà không có lỗi nào ở bất kỳ đâu. Đây là chỗ hợp đồng phải nói rõ: đổi hình dạng body là đổi hợp đồng, kể cả khi mã không đổi. Cách đúng là thêm tham số <code>limit</code> với giá trị mặc định, giữ hình dạng cũ trong một giai đoạn, và ghi thay đổi vào schema để client sinh lại kiểu.</p><p>Ngược lại, nếu backend đổi <code>200</code> thành <code>206</code> cho phản hồi một phần thì script cũ vỡ ngay và ồn ào — đúng như mong muốn, vì nó đang hiểu sai dữ liệu. Bài học: mã đổi thì lỗi lộ ra ngay và rẻ; body đổi âm thầm thì lỗi nằm im trong dữ liệu và chỉ hiện khi ai đó cộng số.</p><p>Câu hỏi tự giải thích: nếu script chỉ kiểm <code>status === 200</code> rồi đọc <code>data.length</code>, dòng nào trong hợp đồng mới khiến nó tính sai, và dòng nào trong code của script đã che mất thay đổi đó?</p>",
  "code": "# FastAPI: hợp đồng là type annotation + Pydantic model.\nfrom uuid import uuid4\n\nfrom fastapi import Depends, FastAPI, HTTPException, Request, Response, status\nfrom fastapi.encoders import jsonable_encoder\nfrom fastapi.exceptions import RequestValidationError\nfrom fastapi.responses import JSONResponse\nfrom pydantic import BaseModel, Field\n\napp = FastAPI()\nBANNED_SKUS = {\"banned-sku\"}\n\n\nasync def new_id() -> str:\n    return uuid4().hex\n\n\nclass CreateOrder(BaseModel):\n    sku: str = Field(min_length=1, max_length=64)\n    qty: int = Field(ge=1, le=999)\n\n\nclass OrderOut(BaseModel):\n    id: str\n    tenant_id: str\n    sku: str\n    qty: int\n\n\nclass Tenant(BaseModel):\n    tenant_id: str\n\n\nasync def get_tenant(request: Request) -> Tenant:\n    # Header do API Gateway chèn sau khi verify JWT, và gateway đã strip header cùng tên do client gửi lên.\n    # Tenant không bao giờ lấy từ body.\n    return Tenant(tenant_id=request.headers[\"x-tenant-id\"])\n\n\ndef envelope(request: Request, code: str, message: str, details=None) -> dict:\n    return {\"error\": {\"code\": code, \"message\": message,\n                      \"details\": details or [],\n                      \"correlation_id\": getattr(request.state, \"cid\", None)}}\n\n\n# Envelope do chính FastAPI sinh ra từ handler, không phải client tự lo.\n@app.exception_handler(RequestValidationError)\nasync def on_validation(request: Request, exc: RequestValidationError) -> JSONResponse:\n    return JSONResponse(\n        status_code=422,\n        content=envelope(request, \"VALIDATION_FAILED\", \"dữ liệu gửi sai hợp đồng\",\n                         jsonable_encoder(exc.errors())),\n    )\n\n\n@app.exception_handler(HTTPException)\nasync def on_business(request: Request, exc: HTTPException) -> JSONResponse:\n    return JSONResponse(\n        status_code=exc.status_code,\n        content=envelope(request, \"BUSINESS_RULE_FAILED\", exc.detail),\n    )\n\n\n@app.post(\n    \"/orders\",\n    response_model=OrderOut,\n    status_code=status.HTTP_201_CREATED,\n    responses={422: {\"description\": \"Validation failed\"}},\n)\nasync def create_order(\n    body: CreateOrder, response: Response, tenant: Tenant = Depends(get_tenant)\n):\n    if body.sku in BANNED_SKUS:\n        raise HTTPException(status_code=409, detail=\"sku đang bị chặn\")\n    order = OrderOut(id=await new_id(), tenant_id=tenant.tenant_id, sku=body.sku, qty=body.qty)\n    response.headers[\"Location\"] = f\"/orders/{order.id}\"   # 201 phải kèm Location\n    return order\n\n# Vue: một client HTTP dùng chung, interceptor dịch lỗi ở một chỗ.\n# api.post(\"/orders\", payload, { headers: { \"Idempotency-Key\": key } })\n# 422 -> chiếu vào từng ô; 401 -> refresh token rồi thử lại một lần;\n# 5xx -> hiện thông báo chung, log correlation id để báo cáo lỗi.",
  "codeNote": "<p><strong>Bốn dòng thật sự đổi trạng thái.</strong></p><ul><li><code>response_model=OrderOut</code>: đây là chỗ quyết định trường nào được ra ngoài. Bỏ nó, dict trả về đi nguyên vẹn và mọi trường nội bộ thành hợp đồng công khai.</li><li><code>status_code=status.HTTP_201_CREATED</code> cùng <code>response.headers[\"Location\"]</code>: hai dòng này biến một lần ghi thành một tài nguyên có địa chỉ, nên client không phải đoán id từ body.</li><li><code>raise HTTPException(status_code=409, ...)</code>: ném lỗi thay vì <code>return {\"ok\": False}</code> là toàn bộ khác biệt của bài; exception handler biến nó thành envelope nhưng mã đã đúng ngay từ chỗ ném.</li><li><code>@app.exception_handler(RequestValidationError)</code>: nếu không đăng ký, <code>422</code> mặc định của FastAPI có hình dạng <code>detail</code> khác hẳn envelope của bạn, và client phải viết hai nhánh.</li></ul><p>Câu hỏi tự giải thích: nếu bỏ dòng <code>response_model</code> nhưng giữ nguyên exception handler, response thành công sẽ khác response lỗi ở điểm nào, và client có phát hiện ra không?</p>",
  "sayIt": ["Tôi mô hình hoá resource trước rồi mới đặt endpoint: danh sách đơn, một đơn theo id, và tạo mới trả 201 kèm Location chứ không phải 200.","Kết quả thành bại đi bằng mã: 422 cho dữ liệu sai hình dạng, 409 cho xung đột nghiệp vụ, 403 cho thiếu quyền; body chỉ chở chi tiết và correlation id.","Một schema sinh ra cả ba thứ: kiểm đầu vào, lọc đầu ra, và tài liệu OpenAPI; client được sinh từ đó nên lệch tên trường đỏ ở CI.","Đổi hợp đồng là đổi hình dạng body chứ không chỉ đổi mã: thêm trường phải có giá trị mặc định, xoá trường phải đi qua giai đoạn chấp nhận cả hai.","Thứ tôi kiểm trên production là phân bố mã theo route và diff openapi.json giữa hai bản deploy, vì cả hai đều là thứ máy đọc được."],
  "qids": ["E01","E02","E11","B14"],
  "refs": ["fastapi-tutorial","mdn-http-overview","mdn-cors"]
},
{
  "provenance": ["Số liệu trong sự cố, dòng thời gian và cách làm ngây thơ là giả định để dựng kịch bản, không phải số đo từ một hệ thống thật.","Các khẳng định về cookie HttpOnly, SameSite, CSRF và về cách một token hết hạn được cấp lại được đối chiếu với tài liệu chính thức trong refs; phần còn lại là mô hình suy ra từ chúng."],
  "id": "L19",
  "stage": 4,
  "stageTitle": "Chặng 4 — Nối hai mảng",
  "title": "Auth xuyên hai phía: token, nơi lưu, interceptor, và ai quyết định quyền",
  "goal": "Trong bài này bạn phải tính được số lời gọi refresh khi bốn mươi request cùng nhận 401, vẽ lại được đường đi của một lần refresh và một lần replay, chỉ ra chỗ nào phải chặn để không lặp vô hạn, và giải thích vì sao một token hợp lệ vẫn chưa phải là một request được phép.",
  "bridge": "Hợp đồng ở bài trước đã chốt rằng 401 là một kết quả máy đọc được, nên interceptor có thể xử lý nó ở một chỗ. Bài này đặt danh tính vào đúng chỗ đó: access token sống ngắn đi kèm mỗi request, refresh token sống dài chỉ để đổi token mới, và cả hai phải không nằm ở nơi mã lạ đọc được.",
  "buildsOn": ["L16","L18"],
  "incident": "<p>Giả sử 9h00 thứ Hai, khoảng 1.000 người dùng mở ứng dụng trong vài phút đầu giờ làm. Access token sống 15 phút và mọi người đăng nhập gần như cùng lúc, nên tới 9h15 gần một nghìn request đồng thời nhận <code>401</code>.</p><p>Interceptor phía Vue được viết theo phản xạ: thấy 401 thì gọi <code>/auth/refresh</code>. Mỗi request tự mở một lời gọi riêng, trong khi endpoint refresh xoay vòng refresh token — mỗi lần cấp cặp mới thì token cũ chết. Chỉ lời gọi đầu thành công; 1.023 lời gọi còn lại mang token đã chết, nhận 401, rồi lại thử lại.</p><p>Log của API ghi 1.024 lời gọi tới <code>/auth/refresh</code> trong một giây. Pool 20 connection tới PostgreSQL bị chính các lời gọi đó chiếm hết, p99 của endpoint refresh lên 6,4 giây, và tab của người dùng quay vô hạn. Không có lỗi 5xx nào, nên alert không kêu.</p>",
  "askFirst": ["Vì sao cùng một sự kiện token hết hạn lại sinh ra hơn một nghìn lời gọi refresh?","Khi lời gọi refresh thứ hai mang một refresh token vừa bị xoay vòng, điều gì khiến nó chắc chắn thất bại?","Nếu kéo hạn của access token lên một ngày, sự cố biến mất hay chỉ dời sang một thời điểm khác với quy mô lớn hơn?"],
  "predict": {"q":"Bốn mươi request cùng nhận 401 một lúc, interceptor dùng một Promise refresh chung. Trong bốn mươi request đó có đúng một request gọi tới /auth/refresh. Refresh chạy bao nhiêu lần, request tới /auth/refresh được xử lý thế nào, và nếu refresh thành công thì bao nhiêu request được gửi lại?","a":"<p>Refresh chạy đúng một lần: request đầu tạo Promise và lưu lại, 39 request còn lại chờ chính Promise đó thay vì tự gọi. Request tới <code>/auth/refresh</code> không được đưa vào nhóm chờ và không được gửi lại — nếu gửi lại, một refresh token đã bị xoay vòng sẽ sinh ra vòng lặp vô hạn, nên nó phải nhận lỗi và kết thúc. Vì vậy khi refresh thành công có 39 request được gửi lại với token mới, còn request thứ bốn mươi thì không. Nếu refresh thất bại, cả 39 request nhận cùng một lỗi, khóa được nhả trong <code>finally</code>, và ứng dụng đăng xuất đúng một lần thay vì thử lại.</p>"},
  "naive": "<p>Cách làm ngây thơ coi refresh là việc của từng request, và coi chỗ lưu token là chi tiết không quan trọng.</p><ul><li><strong>Niềm tin:</strong> thấy 401 thì cứ gọi refresh ngay trong interceptor của request đó, vì mỗi request tự lo cho mình là cách viết ít dòng nhất.</li><li><strong>Vì sao nghe hợp lý:</strong> với một người dùng bấm từng nút, chỉ có một request bay tại một thời điểm, nên refresh chạy đúng một lần và mọi thứ xanh.</li><li><strong>Chỗ chết:</strong> khi nhiều request bay cùng lúc, mỗi request là một sự kiện độc lập, nên n request sinh ra n lời gọi; và vì refresh token xoay vòng, lời đầu làm chết đúng cái token mà những lời còn lại đang cầm.</li></ul>",
  "naiveCode": "// ❌ Cách làm sai phổ biến: lưu token trong localStorage cho tiện, và refresh ngay trong interceptor.\nfunction saveSession(res) {\n  localStorage.setItem(\"access_token\", res.data.access_token)\n  localStorage.setItem(\"refresh_token\", res.data.refresh_token)\n}\n\nhttp.interceptors.response.use(undefined, async (err) => {\n  if (err.response?.status !== 401) throw err\n  // Mỗi request 401 tự gọi refresh của riêng nó.\n  const r = await http.post(\"/auth/refresh\", {\n    refresh_token: localStorage.getItem(\"refresh_token\"),\n  })\n  localStorage.setItem(\"access_token\", r.data.access_token)\n  err.config.headers.Authorization = \"Bearer \" + r.data.access_token\n  return http.request(err.config)\n})",
  "naiveOut": "Ở một người dùng, mọi thứ xanh: token được lưu, header được gắn, và khi 401 xảy ra thì refresh chạy đúng một lần. Ở 1.000 người dùng cùng vào đầu giờ, log của API ghi 1.024 lời gọi /auth/refresh trong một giây và 1.023 lời gọi trả 401, vì xoay vòng làm mọi lời gọi refresh sau lời đầu tiên đều mang token đã chết. Pool 20 connection bị chiếm hết, p99 của endpoint refresh là 6,4 giây, và tab của người dùng quay vô hạn. Song song đó, một lỗi XSS ở bất kỳ thư viện bên thứ ba nào đọc được cả hai token từ localStorage và giả danh người dùng cho tới khi token hết hạn.",
  "timeline": [["08:58:40","Khoảng 1.000 người dùng đăng nhập trong vài phút; mỗi phiên có access token sống 15 phút."],["09:13:55","Những access token đầu tiên hết hạn; p50 của /auth/refresh là 58 ms (giả định)."],["09:14:01","Gần một nghìn request đồng thời nhận 401 và mỗi request tự gọi /auth/refresh."],["09:14:02","Lời gọi refresh đầu tiên xoay vòng token thành công; 1.023 lời gọi còn lại mang refresh token đã chết và nhận 401."],["09:14:03","Mỗi 401 lại kích hoạt một vòng thử lại, nên số lời gọi refresh tăng theo cấp số nhân."],["09:14:06","Pool 20 connection tới PostgreSQL bị chiếm hết; p99 của /auth/refresh là 6,4 giây."]],
  "rootCause": "<p>Ba mắt xích nối tiếp nhau.</p><ol><li>Refresh là việc dùng chung nhưng bị gọi ở cấp từng request, nên mỗi request 401 sinh thêm một lời gọi; số lời gọi tỉ lệ với số request đang bay.</li><li>Vì endpoint xoay vòng token, lời gọi đầu làm chết đúng cái refresh token mà n-1 lời còn lại đang cầm — đây là race condition phía client, không phải lỗi của server.</li><li>Vì mỗi 401 lại kích hoạt một vòng thử lại, bão refresh tự nuôi mình: nó chiếm hết connection pool, đẩy p99 của endpoint refresh lên 6,4 giây, và mọi thứ trông như server chậm chứ không như client sai.</li></ol>",
  "concept": "Access token sống ngắn để mỗi request tự chứng minh danh tính, refresh token sống dài chỉ để đổi token mới; vì refresh là việc dùng chung, mọi request 401 phải chờ đúng một Promise, và quyền vẫn do backend quyết định ở từng request.",
  "mechanism": "<ol><li><strong>Đăng nhập cấp hai thứ khác nhau:</strong> access token trả trong body để Vue giữ trong RAM; refresh token gắn bằng <code>Set-Cookie</code> với <code>HttpOnly</code>, <code>Secure</code>, <code>SameSite=Strict</code> và <code>Path=/auth/refresh</code>, nên mã JavaScript không đọc được và trình duyệt chỉ gửi nó tới đúng một đường dẫn.</li><li><strong>Mỗi request nghiệp vụ tự mang danh tính:</strong> interceptor đọc access token từ RAM và gắn <code>Authorization: Bearer</code>; không đọc từ <code>localStorage</code>, nên một lỗi XSS không rút được token ra khỏi tab.</li><li><strong>Gặp 401 thì gộp, không nhân bản:</strong> nếu biến <code>refreshPromise</code> đã có, request chờ chính Promise đó; nếu chưa, nó tạo một lời gọi <code>/auth/refresh</code> và lưu Promise. Request tới chính endpoint refresh bị loại khỏi nhánh này để không tự gọi lại mình.</li><li><strong>Replay đúng một lần:</strong> có token mới thì gắn header và gửi lại request, đánh dấu <code>_retried</code> để không thử lần hai; khóa được nhả trong <code>finally</code> nên một lần thất bại không treo cả đợt.</li><li><strong>Backend vẫn là nơi quyết định:</strong> mỗi request FastAPI kiểm chữ ký, hạn, loại token, rồi lọc truy vấn theo danh tính lấy từ token; refresh thất bại thì client xoá phiên và điều hướng về đăng nhập đúng một lần.</li></ol>",
  "visuals": [{"id": "flow-auth-refresh", "question": "Bốn mươi request cùng nhận 401 thì refresh chạy mấy lần, và cơ chế nào giữ con số đó ở mức một?", "focus": "Một refresh Promise"}],
  "failureModes": "<p>Bốn kiểu hỏng của chính cách sửa này.</p><ul><li><strong>Promise đã chết vẫn giữ khóa.</strong> Niềm tin sai: gán <code>refreshPromise = null</code> sau <code>await</code> là đủ. Nghe hợp lý vì đường thành công chạy đúng. Điều đúng: phải nhả trong <code>finally</code>, nếu không một lần reject là khóa vĩnh viễn. Phản chứng: từ lúc refresh lỗi, mọi request 401 sau đó treo tới khi người dùng F5, và log chỉ có 401 chứ không có lỗi nào khác.</li><li><strong>Vòng lặp trên chính endpoint refresh.</strong> Niềm tin sai: mọi 401 đều đáng được refresh. Nghe hợp lý vì 401 nghĩa là token hết hạn. Điều đúng: 401 từ <code>/auth/refresh</code> nghĩa là phiên đã chết, phải đăng xuất chứ không thử lại. Phản chứng: số lời gọi <code>/auth/refresh</code> trong log tăng theo cấp số nhân trong vài giây.</li><li><strong>Single-flight chỉ sống trong một tab.</strong> Niềm tin sai: một Promise là đủ cho cả ứng dụng. Nghe hợp lý vì trong một tab nó thật sự đúng. Điều đúng: phạm vi là một tab; hai tab phải đồng bộ qua <code>BroadcastChannel</code> hoặc storage event. Phản chứng: mở hai tab, tab xoay token sau làm tab kia nhận 401 dây chuyền dù người dùng không làm gì.</li><li><strong>Token hợp lệ bị coi là có quyền.</strong> Niềm tin sai: JWT đã ký và có claim role là đủ để cho qua. Nghe hợp lý vì chữ ký đúng thật. Điều đúng: quyền phải kiểm trên từng bản ghi theo danh tính lấy từ token. Phản chứng: đổi id trên URL trả về dữ liệu của tenant khác, và access log ghi 200 chứ không phải 403.</li></ul>",
  "tradeoff": "<p><strong>Cái được.</strong> Access token nằm trong RAM và refresh token trong cookie <code>HttpOnly</code> nghĩa là một lỗi XSS không rút được phiên dài hạn ra khỏi tab; single-flight biến 1.000 lời gọi refresh thành đúng một; và vì endpoint refresh chỉ nhận cookie ở đúng một đường dẫn, bề mặt tấn công hẹp hơn hẳn so với việc gửi token trong body tới mọi nơi.</p><p><strong>Cái mất.</strong> Tải lại trang làm mất access token, nên mỗi lần khởi động phải chạy một lượt refresh im lặng: trang đầu chậm thêm một round trip và phải xử lý trạng thái “đang khôi phục phiên” thay vì hiện form đăng nhập ngay. Nhánh cookie kéo theo CSRF token, cấu hình <code>SameSite</code>, và ràng buộc cookie chỉ đi tới đúng đường dẫn — ba thứ dễ cấu hình sai và khó tái hiện ở máy cá nhân.</p><p><strong>Khi nào xứng đáng.</strong> Khi ứng dụng có dữ liệu đáng giá trị hơn một lần đăng nhập lại, và khi có nhiều request song song trên cùng một trang. Với một trang nội bộ vài người dùng, một token dài hạn trong cookie cũng đủ, và single-flight chỉ là chi phí không cần thiết.</p>",
  "alternatives": "<p><strong>Khi nào chọn cách khác.</strong></p><ul><li><strong>Cookie HttpOnly cho cả hai token, server tự refresh:</strong> chọn khi ứng dụng chạy cùng domain với API. JavaScript không chạm vào token nào, nên không cần single-flight ở client; cái giá là mọi request đều mang cookie nên phải chống CSRF ở mọi endpoint ghi.</li><li><strong>Session opaque trong cơ sở dữ liệu thay vì JWT:</strong> chọn khi cần thu hồi phiên ngay lập tức, ví dụ khoá tài khoản. Cái giá là mỗi request tra một lần kho phiên, nên mất tính stateless ở biên.</li><li><strong>Ủy thác cho một identity provider bên ngoài:</strong> chọn khi xác thực không phải việc của đội bạn. Phía client giữ nguyên cơ chế refresh; cái giá là thêm một hệ thống phải cấu hình, và quyền trên tài nguyên vẫn phải do backend của bạn quyết định.</li><li><strong>Không tách access và refresh:</strong> chỉ hợp lý cho công cụ nội bộ chạy trong mạng riêng, nơi token sống vài giờ và không có ai đánh cắp. Ngay khi có người dùng ngoài, nên tách.</li></ul>",
  "observe": "<p><strong>Bốn tín hiệu, và tín hiệu thứ hai là tín hiệu bạn cần nhất.</strong></p><ul><li><strong>Tỉ lệ 401 theo route.</strong> Tăng đồng thời trên nhiều route là token hết hạn hàng loạt, không phải người dùng gõ sai mật khẩu.</li><li><strong>Số lời gọi <code>/auth/refresh</code> trên mỗi lần hết hạn.</strong> Con số đúng xấp xỉ 1. Vượt 1 rõ rệt nghĩa là single-flight không hoạt động; tăng theo cấp số nhân nghĩa là có vòng lặp.</li><li><strong>p99 của endpoint refresh.</strong> Endpoint này chạm cơ sở dữ liệu nên là chỗ đầu tiên cạn connection pool khi có bão refresh.</li><li><strong>Báo cáo CSP ở chế độ report-only.</strong> Đây là tín hiệu sớm nhất cho biết có XSS đang cố chạy trong tab người dùng, trước cả khi token bị dùng sai.</li></ul>",
  "attacks": [{"q":"Vì sao phải là một Promise dùng chung thay vì một hàng đợi request chờ refresh xong?","a":"<p><strong>Kết luận:</strong> cả hai đều gộp được, nhưng Promise dùng chung ít trạng thái hơn và tự nhả khi xong, nên khó hỏng hơn.</p><p>Một hàng đợi cần ai đó nhớ <em>khi nào</em> mở cửa: refresh thành công thì xả, thất bại thì xả kèm lỗi, và nếu quên một nhánh thì request nằm chờ vĩnh viễn. Promise đã mang sẵn cả hai nhánh đó: <code>resolve</code> xả bình thường, <code>reject</code> lan lỗi cho mọi request đang chờ, và biến trỏ tới nó chỉ cần gán <code>null</code> trong <code>finally</code>.</p><p><strong>Điều kiện:</strong> hàng đợi chỉ hơn khi cần giới hạn số request replay cùng lúc để không dội server lần hai — lúc đó là bài toán rate limit, không phải bài toán refresh. <strong>Dấu hiệu kiểm chứng:</strong> nếu bạn phải viết một hàm <code>flushQueue(error)</code> ở ba chỗ, mô hình đã sai.</p>"},{"q":"Bốn mươi request 401, trong đó mười hai request là POST ghi dữ liệu. Trước khi replay, cần điều kiện gì?","a":"<p><strong>Kết luận:</strong> mỗi request ghi phải mang một <code>Idempotency-Key</code> ổn định từ lần gửi đầu, và replay phải dùng lại đúng key đó.</p><p>Lý do: khi request nhận 401, server đã từ chối trước khi ghi, nên replay thường an toàn. Nhưng nếu 401 đến từ một proxy sau khi server đã ghi, hoặc nếu lần replay bị timeout rồi thử lại lần nữa, thì không có key là hai bản ghi. Key phải sinh ở phía client một lần cho mỗi hành động của người dùng, không sinh lại trong interceptor.</p><p><strong>Điều kiện:</strong> request đọc thì không cần key, chỉ cần bảo đảm không replay quá một lần. <strong>Dấu hiệu kiểm chứng:</strong> đếm số bản ghi có cùng <code>Idempotency-Key</code> trong cơ sở dữ liệu; nếu lớn hơn 1 thì tầng ghi đang không idempotent.</p>"},{"q":"Nếu chuyển refresh token từ localStorage sang cookie HttpOnly, rủi ro mới là gì và bù bằng cách nào?","a":"<p><strong>Kết luận:</strong> rủi ro mới là CSRF, và cách bù là <code>SameSite</code> cộng kiểm tra nguồn gốc request ở server.</p><p>Cookie được trình duyệt tự gửi kèm mọi request tới đúng domain, kể cả request do một trang khác khởi phát. Vì vậy kẻ tấn công không cần đọc token — chỉ cần dụ trình duyệt nạn nhân gọi <code>/auth/refresh</code> hoặc một endpoint ghi. Bù lại: đặt <code>SameSite=Strict</code> hoặc <code>Lax</code>, giới hạn <code>Path</code> của cookie, kiểm header <code>Origin</code> hoặc <code>Sec-Fetch-Site</code> ở server, và yêu cầu một header tuỳ biến mà form HTML từ trang lạ không gửi được.</p><p><strong>Điều kiện:</strong> nếu API và ứng dụng khác site, cookie cần <code>SameSite=None; Secure</code> và CSRF token là bắt buộc, không thể dựa vào <code>SameSite</code>. <strong>Dấu hiệu kiểm chứng:</strong> một request POST từ trang khác phải bị từ chối với 403, và log phải ghi rõ lý do từ chối.</p>"},{"q":"Single-flight không giải quyết được những gì?","a":"<p><strong>Kết luận:</strong> nó chỉ gộp các request 401 trong một tab. Nó không thu hồi quyền, không đồng bộ giữa các tab, và không thay thế kiểm quyền ở backend.</p><ul><li>Không đồng bộ nhiều tab hay nhiều thiết bị: mỗi tab có biến Promise riêng, nên hai tab vẫn xoay vòng token của nhau; cần <code>BroadcastChannel</code> hoặc để server cho phép một cửa sổ ân hạn ngắn.</li><li>Không thu hồi phiên: token đã phát hành vẫn dùng được tới khi hết hạn, trừ khi server tra thêm trạng thái phiên hoặc <code>jti</code>.</li><li>Không thay kiểm quyền: một token hợp lệ vẫn có thể trỏ tới bản ghi của người khác; quyền trên tài nguyên luôn là việc của backend ở từng request.</li></ul><p><strong>Điều kiện:</strong> nếu ứng dụng chỉ mở một tab và không cần thu hồi tức thời, ba giới hạn trên không gây hậu quả. <strong>Dấu hiệu kiểm chứng:</strong> mở hai tab và đăng xuất ở một tab; nếu tab còn lại vẫn gọi được API thì đồng bộ phiên chưa tồn tại.</p>"}],
  "anchor": "Refresh là việc dùng chung: mọi request 401 chờ đúng một Promise, và backend vẫn quyết định quyền ở từng request.",
  "say30": "Access token sống ngắn và đi kèm mọi request, còn refresh token sống lâu và chỉ dùng để đổi access token mới, nên khi access token bị lộ thì thiệt hại chỉ kéo dài tới lúc nó hết hạn. Khi token hết hạn đồng loạt, nếu mỗi request 401 tự refresh thì hàng nghìn lời gọi phá nhau vì refresh token xoay vòng. Tôi gộp bằng single-flight: một Promise dùng chung, nhả khóa trong finally, cờ đã thử để không lặp vô hạn.",
  "say90": "[Nêu vấn đề (30s)]: Access token sống ngắn đi kèm mọi request, refresh token sống lâu chỉ để đổi token mới, nên khi access token bị lộ thì thiệt hại chỉ kéo dài tới lúc nó hết hạn. Nỗi đau là token hết hạn đồng loạt: một nghìn request nhận 401 cùng lúc, mỗi request tự gọi refresh, và vì refresh token xoay vòng nên chỉ lời đầu sống.\n\n[Cơ chế (45s)]: Interceptor giữ một biến refreshPromise dùng chung. Request 401 đầu tiên tạo Promise và lưu lại, 39 request còn lại chờ chính nó; request tới endpoint refresh bị loại khỏi nhánh chờ để không lặp vô hạn; khóa được nhả trong finally và mỗi request chỉ replay một lần nhờ cờ đã thử. Về nơi lưu: access token trong RAM, refresh token trong cookie HttpOnly SameSite Strict ở đúng một đường dẫn, nên XSS không đọc được. Backend vẫn kiểm chữ ký, hạn, loại token và quyền trên từng bản ghi.\n\n[Ranh giới (15s)]: Single-flight chỉ sống trong một tab, không thu hồi được phiên đã phát hành, và không thay thế kiểm quyền ở backend. Cookie còn kéo theo rủi ro CSRF phải bù bằng SameSite và kiểm Origin.",
  "body": "<p><strong>Ví dụ chuyển giao: cùng một cơ chế, khác chỗ đặt.</strong> Một dashboard mở ra và bắn 18 lời gọi song song. Nếu người dùng quay lại sau 16 phút và bấm làm mới, cả 18 lời gọi cùng nhận 401 và cùng đòi refresh; lần xoay vòng đầu tiên giết đúng cái token mà 17 lời còn lại đang cầm, nên cả trang đứng hình. Với single-flight, chỉ một lời gọi refresh tồn tại và 17 lời còn lại chờ nó; trang chậm thêm đúng một round trip, rồi tất cả đi tiếp.</p><p>Cùng cơ chế đó xuất hiện ở những chỗ không có trình duyệt. Một script Python gọi API bằng <code>requests</code> cũng gặp 401 và cũng cần một khoá dùng chung, chỉ khác là khoá nằm trong <code>asyncio.Lock</code> thay vì một biến Promise. Một cron job chạy đồng thời trên nhiều máy thì không có khoá nào dùng chung được — lúc đó phải để server cho phép một cửa sổ ân hạn ngắn, hoặc chấp nhận đăng nhập lại.</p><p><strong>Cách nhận ra bài toán này trong ba mươi giây.</strong> Ba dấu hiệu đi cùng nhau: nhiều lời gọi tới cùng một endpoint xác thực trong một giây; chúng xuất hiện đồng thời chứ không rải rác; và endpoint đó chạm cơ sở dữ liệu nên p99 của nó là thứ đầu tiên xấu đi. Khi thấy cả ba, nguyên nhân gần như luôn là một việc dùng chung đang bị gọi ở cấp từng request.</p><p><strong>Điều hay bị hỏi tiếp:</strong> nếu refresh token nằm trong cookie thì tại sao vẫn cần refresh? Vì cookie chỉ là chỗ cất, không phải chỗ quyết định: nó sống lâu hơn access token và chỉ đi tới một đường dẫn, nên nó không thể thay access token trong mọi request nghiệp vụ. Và nếu đã gộp refresh thì có cần chống trùng ở server không? Có — khoá phía client chỉ giảm số lời gọi trong một tab, còn hai tab hoặc hai thiết bị vẫn có thể đua nhau, nên phía server vẫn cần biết token nào đã dùng.</p>",
  "code": "// ✅ Cách làm chuẩn: một Promise refresh dùng chung cho cả đợt request 401.\nlet accessToken = null;      // chỉ nằm trong RAM, không vào localStorage\nlet refreshPromise = null;   // khoá single-flight\n\n// refreshFn do tầng gọi truyền vào (client HTTP của bạn). Hàm này không tự\n// mở kết nối nào, và refreshFn là client gốc chứ không phải hàm api() bên\n// dưới, nên request refresh không bao giờ quay lại đây thành vòng lặp.\nfunction getAccessToken(refreshFn) {\n  refreshPromise = refreshPromise ?? refreshFn();   // gộp: đợt sau dùng lại\n  return refreshPromise;\n}\n\n// Nhận thẳng đối tượng phản hồi { status, data } từ client, không tự gọi mạng.\nasync function handle401(res, { refreshFn, retry, retried = false }) {\n  if (res.status !== 401 || retried) return res;   // 401 lần hai: trả về\n  try {\n    accessToken = await getAccessToken(refreshFn);\n  } finally {\n    refreshPromise = null;      // nhả khoá kể cả khi refresh reject\n  }\n  return retry({ Authorization: `Bearer ${accessToken}`, retried: true });\n}\n",
  "codeNote": "<p><strong>Bốn khối quyết định trong đoạn code trên.</strong></p><ul><li><strong><code>accessToken</code> là một biến trong RAM, không phải một kho lưu:</strong> tải lại trang là mất, và đó là cái giá đã chốt ở phần đánh đổi; đổi lại không có thư viện bên thứ ba nào đọc được nó.</li><li><strong><code>refreshFn</code> được truyền vào, không tự gọi trong hàm:</strong> đây là chỗ chặn vòng lặp. Nếu bước refresh tự đi qua <code>handle401</code>, một 401 từ chính nó sẽ lại kích hoạt nhánh chờ và tạo vòng vô hạn; tách client gốc ra khỏi interceptor khiến việc đó không thể xảy ra. Cookie <code>HttpOnly</code> đi kèm request là do client gốc bật <code>withCredentials</code>, nên mã JavaScript không bao giờ chạm vào refresh token.</li><li><strong><code>refreshPromise ?? refreshFn()</code> là toàn bộ cơ chế single-flight:</strong> request đầu tiên tạo Promise, mọi request sau trong cùng đợt đọc lại đúng Promise đó thay vì tạo lời gọi mới. Không có hàng đợi, không có bộ đếm, nên không có trạng thái nào để quên.</li><li><strong><code>finally { refreshPromise = null }</code> và cờ <code>retried</code>:</strong> <code>finally</code> nhả khoá kể cả khi refresh reject, nên một lần thất bại không treo cả đợt; <code>retried</code> bảo đảm mỗi request chỉ replay một lần, nên server trả 401 lần hai thì lỗi nổi lên cho người gọi chứ không thành vòng lặp.</li></ul>",
  "sayIt": ["Access token sống ngắn và đi kèm mỗi request, còn refresh token sống lâu chỉ để đổi lấy access token mới, nên khi access token bị lộ thì thiệt hại chỉ kéo dài tới lúc nó hết hạn.","Vue chỉ giữ token và gắn header, còn FastAPI mới là bên kiểm chữ ký, hạn, loại token và quyền trên từng tài nguyên, kể cả tenant và chủ sở hữu.","Tôi không để token trong localStorage vì XSS đọc được; tôi chọn access token trong memory và refresh token trong cookie HttpOnly, đổi lại lúc khởi động phải chạy một lượt refresh im lặng.","Khi gặp 401 thì phải refresh đúng một lần cho cả đợt request và chặn vòng lặp bằng cờ đã thử, nếu không ứng dụng sẽ treo với hàng trăm request cùng chờ.","Xoá token ở client không huỷ được phiên ở server, nên tôi xoay vòng refresh token và ghi jti để token cũ không dùng lại được."],
  "qids": ["E05","C10","B08","B14"],
  "refs": ["owasp-api-security","mdn-cookies","mdn-http-headers"]
},
{
  "provenance": ["Số liệu trong sự cố, dòng thời gian và cách làm ngây thơ là giả định để dựng kịch bản, không phải số đo từ một hệ thống thật.","Các khẳng định về cách S3 kiểm chữ ký, về hạn của presigned URL, về head_object và về hành vi của Versioning được đối chiếu với tài liệu chính thức trong refs; phần còn lại là mô hình suy ra từ chúng."],
  "id": "L20",
  "stage": 4,
  "stageTitle": "Chặng 4 — Nối hai mảng",
  "title": "Upload lên S3: ký quyền ghi, rồi xác nhận thứ thật sự nằm trong bucket",
  "goal": "Trong bài này bạn phải chỉ ra được, với một object đang nằm trong bucket, những gì phải đọc từ head_object để quyết định bản ghi upload được chuyển sang READY, và giải thích vì sao một presigned URL còn hạn không chứng minh được tệp nằm đó đúng như đã khai.",
  "bridge": "Bài trước chốt rằng client chỉ giữ token và gắn header, còn server mới quyết định quyền. Bài này dùng đúng header đó để xin một quyền hẹp hơn nhiều: quyền ghi một object, trong mười phút, trên một key do server đặt. Byte không đi qua API nữa, nên câu hỏi mới là ai xác nhận thứ đã nằm trong bucket.",
  "buildsOn": ["L05","L18","L19"],
  "incident": "<p>Giả định một buổi sáng có 10.000 người dùng tải tệp, trung bình 5 MB một tệp. Hệ thống không sập; ba chuyện nhỏ hơn mới là thứ khiến đội phải họp.</p><p>Một người dùng mạng 3G nhận presigned URL lúc 10h04, tới 10h15 mới bắt đầu PUT thì trình duyệt nhận 403. Bấm gửi lại cũng 403, vì hạn được tính từ lúc ký chứ không từ lúc byte bắt đầu đi.</p><p>Trong bucket có 1.240 object không có hàng metadata nào trỏ tới. Người dùng PUT xong 5 MB rồi mất mạng trước khi gọi xác nhận; object nằm lại, hàng bản ghi kẹt ở trạng thái chờ, và hoá đơn dung lượng tăng mỗi tháng mà không ai giải thích được.</p><p>Chuyện đáng sợ nhất: một object 900 MB nằm ở key đã cấp cho một ảnh đại diện 5 MB, và nó mang <code>Content-Type: text/html</code>. URL đúng người, đúng key, S3 đã nhận, vì chữ ký không mang theo ràng buộc kích thước nào.</p>",
  "askFirst": ["Vì sao URL còn hạn mười phút lại hết hạn đúng lúc người dùng mạng chậm cần nó nhất?","Nếu client đã PUT xong mà lời gọi xác nhận thất bại, thứ gì trong hệ thống biết tệp đó đang tồn tại?","API đã kiểm kích thước và loại tệp rồi, vì sao vẫn có một object 900 MB nằm trong bucket?"],
  "predict": {"q":"Hai lời gọi PUT cùng một presigned URL, cùng một key, cả hai trước hạn: lần đầu 5 MB, lần hai 900 MB. Nếu bucket không bật Versioning, head_object ở bước xác nhận đọc được gì, và bản ghi upload nên kết thúc ở trạng thái nào?","a":"<p><code>head_object</code> trả về bản mới nhất của key, tức là 900 MB, nên phép so kích thước bắt được và bản ghi phải kết thúc ở trạng thái lỗi. Nhưng cách sửa mới là phần đáng nói: xoá object theo key sẽ xoá luôn bản 5 MB hợp lệ, và nếu bản ghi đã READY từ trước thì mọi URL đọc phát hành theo key sẽ trả về bản độc. Nếu bucket có Versioning, <code>head_object</code> trả kèm <code>VersionId</code> của bản mới nhất, nên phải ghim đúng version đó ở bước xác nhận và ở mọi lần phục vụ; bản cũ vẫn nằm trong bucket và vẫn tốn dung lượng cho tới khi có lifecycle dọn. Nhánh thứ ba: nếu lần PUT thứ hai diễn ra sau khi bản ghi đã READY, thì không có bước xác nhận nào chạy lại để bắt nó — đó là lý do phải ký hạn ngắn và ghim version chứ không chỉ kiểm một lần.</p>"},
  "naive": "<p>Cách làm ngây thơ coi presigned URL là bằng chứng về nội dung, và coi hạn URL là chi tiết cấu hình.</p><ul><li><strong>Niềm tin:</strong> S3 chỉ nhận đúng thứ client đã khai, nên cấp URL xong là coi như tệp đã đúng; bước xác nhận chỉ cần đánh dấu bản ghi sang READY.</li><li><strong>Vì sao nghe hợp lý:</strong> với một người dùng gửi một ảnh đúng như khai, mọi thứ khớp, và bước xác nhận chỉ tốn thêm một lời gọi vô nghĩa.</li><li><strong>Chỗ chết:</strong> URL là quyền dùng lại được trong suốt thời hạn và chữ ký không mang kích thước, nên một URL đã cấp có thể nhận byte khác hẳn lời khai; và nếu bản ghi không được ghi trước khi ký, một lần xác nhận thất bại là object không còn ai chủ.</li></ul>",
  "naiveCode": "# ❌ Cách làm sai phổ biến: API nhận key từ client, ký URL dài hạn, không ràng buộc header.\n@app.post(\"/uploads/presign\")\nasync def presign(body: PresignIn, user=Depends(current_user)):\n    key = body.file_name            # client tự chọn key: có thể ghi đè tệp của người khác\n    url = s3.generate_presigned_url(\n        ClientMethod=\"put_object\",\n        Params={\"Bucket\": BUCKET, \"Key\": key},\n        ExpiresIn=86400,            # một ngày, cho tiện\n    )\n    return {\"url\": url, \"key\": key}\n\n# Client PUT thẳng lên S3 bằng chính URL này. Không có bước xác nhận,\n# không có bản ghi metadata, không có gì ràng buộc nội dung.",
  "naiveOut": "Với 10 người dùng thử nội bộ, mọi thứ xanh: URL được cấp, tệp lên, và không ai để ý là không có hàng metadata nào. Ở 10.000 người dùng, ba dấu vết xuất hiện. Kiểm tra <code>head_object</code> một object nằm ở key của một ảnh đại diện thấy <code>ContentLength</code> khoảng 900 MB và <code>ContentType</code> là <code>text/html</code>, vì chữ ký không mang theo ràng buộc kích thước lẫn loại nội dung nào để S3 thực thi. Trong danh sách object có 1.240 object không có hàng metadata tương ứng, mỗi object 5 MB, tổng khoảng 6 GB dữ liệu không ai quản lý. Và vì URL sống một ngày, một tệp đã được quét xong vẫn có thể bị ghi đè bằng nội dung khác trong cùng ngày hôm đó.",
  "timeline": [["10:02:00","10.000 người dùng bắt đầu tải tệp, mỗi tệp trung bình 5 MB (giả định)."],["10:04:12","Một người dùng mạng 3G nhận presigned URL sống 10 phút."],["10:15:12","PUT đầu tiên của người đó nhận 403 vì URL đã hết hạn; bấm gửi lại cũng 403."],["10:31:40","Một client PUT xong 5 MB rồi mất mạng trước khi gọi xác nhận."],["11:00:00","Kiểm tra ngẫu nhiên thấy object 900 MB ở key của một ảnh đại diện, mang Content-Type text/html."],["Cuối ngày","Đếm ra 1.240 object không có hàng metadata nào trỏ tới, khoảng 6 GB (giả định)."]],
  "rootCause": "<p>Ba mắt xích, và mắt thứ ba là mắt khó thấy nhất.</p><ol><li>Hạn của URL được tính từ lúc ký, không từ lúc byte bắt đầu đi, nên người dùng mạng chậm chắc chắn gặp 403 và không có cách nào cứu URL đã hết hạn.</li><li>Nếu bản ghi upload không được ghi trước khi ký, một lần xác nhận thất bại là object không còn ai chủ: nó nằm trong bucket, tốn dung lượng, và không có hàng nào trỏ tới để dọn.</li><li>Presigned URL là quyền dùng lại được trong suốt thời hạn và chữ ký không mang ràng buộc kích thước, nên một URL đã cấp có thể nhận byte khác hẳn lời khai; và nếu đọc lẫn phục vụ đều theo key thay vì theo version, thì byte được kiểm và byte được phục vụ là hai đối tượng khác nhau.</li></ol>",
  "concept": "Presigned URL là quyền ghi có hạn trên một key do server đặt, không phải bằng chứng về nội dung; vì vậy server ghi bản ghi chờ trước khi ký, và chỉ chuyển sang READY sau khi head_object đối chiếu kích thước, key và metadata của đúng version đã quét.",
  "mechanism": "<ol><li><strong>Xin quyền ghi:</strong> Vue gửi loại tệp, kích thước khai báo và content type. FastAPI từ chối ngay bằng 413 nếu vượt hạn mức và 415 nếu loại không nằm trong allowlist, rồi tự sinh key dạng <code>uploads/{tenant}/{kind}/{uuid}</code>; client không bao giờ chọn key.</li><li><strong>Ghi bản ghi trước, ký sau:</strong> bản ghi PENDING được ghi vào PostgreSQL trước khi ký, rồi URL được ký cho đúng một thao tác PUT trên đúng key đó, kèm content type và hạn ngắn. Hạn tính từ lúc ký, nên URL sống mười phút kể từ giây phút này, không phải từ lúc người dùng bấm gửi.</li><li><strong>Byte đi thẳng:</strong> trình duyệt PUT lên S3, API không thấy byte nào, nên mọi thứ API biết về tệp đều là lời khai cho tới bước sau.</li><li><strong>Xác nhận bằng head_object:</strong> endpoint confirm đọc <code>head_object</code> của key, lấy kích thước thật, content type, <code>VersionId</code> và metadata tuỳ chỉnh, so với bản ghi; khớp thì chuyển SCANNING rồi quét nội dung và chỉ sau đó mới READY, lệch thì xoá đúng <code>VersionId</code> vừa đọc và đánh dấu bản ghi là lỗi.</li><li><strong>Dọn phần dư:</strong> một worker định kỳ tìm bản ghi PENDING quá hạn, kiểm object có thật bằng <code>head_object</code> rồi mới xoá, để không xoá nhầm object mà lời xác nhận đang trên đường tới.</li></ol>",
  "visuals": [{"id": "flow-upload-confirm", "question": "Làm sao biết object thật trong S3 khớp với bản ghi upload, khi API không hề thấy byte nào?", "focus": "head_object"}],
  "failureModes": "<p>Bốn kiểu hỏng của chính cách sửa này.</p><ul><li><strong>Hạn ngắn đẩy lỗi sang người mạng chậm.</strong> Niềm tin sai: rút hạn URL xuống là an toàn hơn. Nghe hợp lý vì cửa sổ bị lạm dụng hẹp lại thật. Điều đúng: nó không chặn được ghi đè trong hạn, mà chỉ dời lỗi sang nhóm người dùng mạng chậm nhất, và 403 không nói cho client biết phải xin URL mới. Phản chứng: tỉ lệ 403 tăng đúng ở nhóm mạng chậm, còn số object bị ghi đè không đổi.</li><li><strong>Dọn object mồ côi xoá nhầm.</strong> Niềm tin sai: bản ghi quá hạn thì object xoá được. Nghe hợp lý vì bản ghi quá hạn trông như rác. Điều đúng: phải chờ dài hơn thời gian xác nhận tối đa và phải kiểm object có thật trước khi xoá. Phản chứng: người dùng báo tệp vừa tải xong đã biến mất, và log confirm ghi 404 ở bước head_object.</li><li><strong>Versioning phình dung lượng.</strong> Niềm tin sai: bật Versioning là xong phần an toàn. Nghe hợp lý vì version làm object bất biến thật. Điều đúng: mỗi lần ghi sinh một version không tự mất, nên phải có lifecycle dọn version cũ. Phản chứng: dung lượng bucket tăng đơn điệu dù số tệp không đổi.</li><li><strong>SCANNING thành trạng thái chết.</strong> Niềm tin sai: quét xong thì bản ghi tự sang READY. Nghe hợp lý vì đường thành công chạy đúng. Điều đúng: job quét cần timeout và một hàng đợi lỗi, nếu không bản ghi kẹt vĩnh viễn ở giữa. Phản chứng: hàng loạt bản ghi đứng ở SCANNING và người dùng thấy trạng thái “đang xử lý” mãi không thôi.</li></ul>",
  "tradeoff": "<p><strong>Cái được.</strong> Byte không đi qua API, nên không tốn băng thông hai lần và không chạm trần kích thước body của tầng trước; quyền ghi chỉ tồn tại trong mười phút và chỉ trên một key do server đặt; và vì chỉ bản ghi READY mới được phục vụ, một tệp chưa qua kiểm tra không bao giờ có URL đọc.</p><p><strong>Cái mất.</strong> Ba request thay vì một, kèm một trạng thái trung gian phải định nghĩa rõ và một worker dọn dẹp phải chạy đúng. Versioning tốn dung lượng gấp nhiều lần số tệp thật, và quét nội dung thêm độ trễ vào nhánh nghiệp vụ: người dùng tải xong vẫn phải chờ mới thấy tệp. Hạn ngắn cũng đẩy một phần lỗi sang người dùng mạng chậm.</p><p><strong>Khi nào xứng đáng.</strong> Khi tệp là dữ liệu người dùng thật và sẽ được phục vụ lại cho người khác. Với một tệp CSV nội bộ vài trăm KB mà chỉ một máy đọc, upload qua API trực tiếp đơn giản hơn nhiều và không cần ba bước này.</p>",
  "alternatives": "<p><strong>Khi nào chọn cách khác.</strong></p><ul><li><strong>Presigned POST thay vì PUT:</strong> chọn khi cần S3 tự chặn kích thước, vì policy của POST nhận điều kiện <code>content-length-range</code>, thứ mà một PUT không ký được. Cái giá là form fields phức tạp hơn và khó dùng cho tệp lớn.</li><li><strong>Multipart upload:</strong> chọn khi tệp lên tới hàng trăm MB, vì chia phần cho phép tải lại đúng phần hỏng thay vì cả tệp. Cái giá là mỗi phần là một lời gọi, và phải tự quản lý vòng đời của phiên multipart.</li><li><strong>Upload qua API trực tiếp:</strong> chọn khi tệp nhỏ và hiếm, vì chỉ một request, không có trạng thái trung gian, không có object mồ côi. Cái giá là byte đi qua server hai lần và chạm trần body.</li><li><strong>Bucket công khai có tiền tố ngẫu nhiên:</strong> chỉ hợp lý cho tài nguyên tĩnh không riêng tư. Ngay khi tệp thuộc về một người dùng cụ thể, bucket phải private và mọi lần đọc phải đi qua một URL có hạn.</li></ul>",
  "observe": "<p><strong>Bốn tín hiệu, xếp theo thứ tự bạn nên xem trước.</strong></p><ul><li><strong>Khoảng cách giữa số object và số hàng READY.</strong> Đếm định kỳ cả hai; khoảng cách chính là số tệp không ai chủ, và nó phải tiến về 0 chứ không chỉ dao động.</li><li><strong>Số bản ghi PENDING quá hạn.</strong> Tăng đều nghĩa là bước xác nhận đang thất bại ở một tỉ lệ cố định, thường vì mạng di động hoặc vì endpoint confirm chậm.</li><li><strong>Tỉ lệ lệch giữa kích thước thật và kích thước khai.</strong> Ghi cả hai ở bước xác nhận. Khác 0 nghĩa là chữ ký đang thiếu một ràng buộc, và đây là tín hiệu bảo mật chứ không phải tín hiệu trải nghiệm.</li><li><strong>Số bản ghi đứng ở SCANNING quá lâu.</strong> Đây là hàng đợi quét bị nghẽn hoặc job chết, và người dùng đang thấy trạng thái chờ mà không ai xử lý.</li></ul>",
  "attacks": [{"q":"Tại sao trong hàm generate_presigned_url(ClientMethod='put_object') bạn không đưa luôn ContentLength vào Params để cấm người dùng đẩy file 5GB lên S3?","a":"<p> <strong>Chốt:</strong> Trong chuẩn Presigned <code>PUT</code> kết hợp với trình duyệt, việc ký cứng một con số <code>ContentLength</code> dễ gặp rắc rối với cơ chế kiểm tra header của trình duyệt/SDK, hoặc nếu không ký thì kẻ tấn công có thể khai báo <code>size = 1MB</code> lúc xin URL rồi <code>PUT</code> thật một file <code>5GB</code> lên S3. </p>\n<ul>\n <li> <strong>Hai giải pháp chặn dung lượng thật ở tầng S3: </strong>\n <ol>\n <li><strong>Chuyển sang <code>generate_presigned_post</code> (Presigned POST Policy):</strong> Cho phép ký một chính sách JSON có điều kiện <code>[\"content-length-range\", 1, 10485760]</code> (từ 1 byte đến 10MB). Khi dùng Presigned POST, S3 kiểm tra trực tiếp luồng byte tải lên và ngắt kết nối ngay lập tức nếu vượt quá 10MB. </li>\n <li> <strong>Nếu giữ Presigned PUT:</strong> Kiểm tra lại <code>head[\"ContentLength\"] &gt; MAX_BYTES</code> ngay trong hàm <code>confirm</code> / S3 Event Worker (như trong mẫu code chuẩn) để xóa ngay phiên bản vi phạm, kết hợp cấu hình <strong>S3 Lifecycle Rule </strong> tự động xóa mọi đối tượng ở nhánh tạm/chưa <code>READY</code> sau 24 giờ. </li>\n </ol>\n </li>\n</ul>"},{"q":"Nếu tôi giảm thời gian sống (ExpiresIn) của Presigned PUT URL xuống còn 60 giây thì có ngăn được trò 'PUT ảnh sạch để qua kiểm tra rồi PUT đè file độc lên cùng key' không?","a":"<p> <strong>Chốt:</strong> <strong>Hoàn toàn không ngăn được.</strong> Kẻ tấn công dùng script tự động chỉ mất <strong>vài trăm mili-giây</strong> để bắn liên tiếp 2 lệnh <code>PUT</code>, nên dù <code>ExpiresIn</code> là 600 giây hay 5 giây thì lỗ hổng tranh chấp thời gian ( <code>TOCTOU - Time-of-Check to Time-of-Use</code>) vẫn mở toang.</p>\n<ul>\n <li> <strong>Bản chất của Presigned PUT URL:</strong> S3 không cung cấp cơ chế \"URL chỉ dùng 1 lần\" trong tài liệu đã đọc. Chừng nào đồng hồ chưa vượt quá <code>X-Amz-Expires</code>, cùng một URL đó có thể được gọi <code>PUT</code> hàng백 lần lên đúng <code>Key</code> đó.</li>\n <li><strong>Hai cách khóa triệt để cửa sổ ghi đè:</strong> (1) Bật <strong>S3 Versioning </strong> và ghim cứng <code>VersionId</code> tại thời điểm bắt đầu quét; mọi lệnh đọc về sau chỉ đọc đúng <code>VersionId</code> đã duyệt. (2) Hoặc tách <strong>2 vùng/2 bucket </strong>: cấp Presigned URL chỉ cho phép <code>PUT</code> vào vùng cách ly <code>quarantine-bucket</code>; ngay khi nhận sự kiện upload, Worker copy đối tượng đó sang vùng nội bộ <code>verified-bucket</code> (nơi Client hoàn toàn không có URL ghi) rồi mới tiến hành quét và công bố.</li>\n</ul>"},{"q":"Khi bật S3 Bucket Versioning, nếu phát hiện file độc hại và gọi s3.delete_object(Bucket=..., Key=...) mà quên truyền VersionId thì chuyện gì xảy ra?","a":"<p><strong>Chốt:</strong> <strong>File độc hại KHÔNG HỀ bị xóa khỏi S3! </strong> Bạn vẫn phải trả tiền lưu trữ cho nó và bất kỳ code nào đọc theo <code>VersionId</code> cũ vẫn tải được nguyên vẹn file độc đó.</p>\n<ul>\n <li><strong>Cơ chế Delete Marker của S3 Versioning: </strong> Trên một bucket đã bật Versioning, lệnh <code>delete_object(Bucket, Key)</code> không có <code>VersionId</code> chỉ tạo thêm một nhãn đánh dấu xóa (<code>Delete Marker</code>) đặt lên trên cùng, còn phiên bản chứa nội dung tệp bên dưới vẫn nằm nguyên trên đĩa của AWS.</li>\n <li><strong>Cách xóa vĩnh viễn:</strong> Bắt buộc phải truyền tường minh <code>s3.delete_object(Bucket=BUCKET, Key=object_key, VersionId=version_id)</code> (cần quyền IAM <code>s3:DeleteObjectVersion</code>), đồng thời cấu hình <code>NoncurrentVersionExpiration</code> trong S3 Lifecycle để tự động dọn các phiên bản cũ bị bỏ rơi. </li>\n</ul>"},{"q":"Worker đã đọc 8 byte đầu tiên (Magic Bytes) và xác nhận đúng chữ ký của file PDF/PNG rồi, tại sao vẫn phải qua bước quét Virus và giữ trạng thái SCANNING?","a":"<p><strong>Chốt:</strong> Vì kiểm tra <code>Magic Bytes</code> và <code>Quét mã độc (Antivirus/Malware Scan)</code> trả lời hai câu hỏi bảo mật ở hai tầng hoàn toàn khác nhau.</p>\n<ul>\n <li> <strong>Tầng 1 - Magic Bytes (Nhanh &amp; Rẻ - Tốn 8 byte): </strong> Chỉ xác nhận <em>\"Cấu trúc đầu tệp có đúng là định dạng PNG/PDF như đã khai báo không?\"</em> để chặn ngay trò đổi tên <code>shell.exe</code> thành <code>avatar.png</code> mà không tốn công tải cả file 20MB. </li>\n <li> <strong>Tầng 2 - Quét toàn phần &amp; Khử độc (Sâu &amp; Đắt):</strong> Một file PDF hoàn toàn hợp lệ (bắt đầu đúng bằng <code>%PDF-1.7</code>) vẫn có thể nhúng mã khai thác lỗ hổng đọc PDF hoặc JavaScript độc hại ở trang thứ 10; một file ảnh PNG hợp lệ vẫn có thể là một <em>Polyglot file</em> (vừa có đầu PNG vừa chứa payload ở phần thân) hoặc chứa <em>Decompression Bomb</em> (ảnh 1MB giải nén ra 20GB RAM làm sập server). Do đó phải quét toàn bộ nội dung (hoặc tái tạo lại ảnh - Image Re-encoding) trước khi chuyển sang <code>READY</code>.</li>\n</ul>"}],
  "anchor": "Presigned URL chỉ thực thi đúng những gì đã ký vào nó; thứ không ký chỉ là lời khai, không phải cam kết.",
  "say30": "Byte của tệp không đi qua API: Vue xin presigned URL, server tự sinh key, ký content type và hạn mười phút, rồi trình duyệt PUT thẳng lên S3. Vì vậy API không thấy nội dung nào, nên bước xác nhận phải đọc head_object để so kích thước thật, key và metadata của đúng version, khớp mới chuyển READY, lệch thì xoá và đánh dấu lỗi.",
  "say90": "[Nêu vấn đề (30s)]: Presigned URL là quyền ghi có hạn trên một key, không phải bằng chứng về nội dung. Nỗi đau đến từ ba phía cùng lúc: hạn được tính từ lúc ký nên người mạng chậm nhận 403, một lần xác nhận thất bại để lại object không ai chủ, và một URL đã cấp vẫn nhận được byte khác hẳn lời khai vì chữ ký không mang kích thước.\n\n[Cơ chế (45s)]: Server tự sinh key có tiền tố tenant, ghi bản ghi chờ trước khi ký, rồi ký PUT kèm content type và hạn ngắn. Trình duyệt PUT thẳng lên S3 nên API không thấy byte nào. Bước xác nhận đọc head_object để lấy kích thước thật, content type, VersionId và metadata, rồi so với bản ghi: khớp thì chuyển sang quét nội dung và chỉ sau đó mới READY, lệch thì xoá đúng version vừa đọc và đánh dấu lỗi. Versioning giữ object bất biến, để byte được quét và byte được phục vụ luôn là một.\n\n[Ranh giới (15s)]: Ba bước kéo theo một trạng thái trung gian phải định nghĩa rõ và một worker dọn dẹp phải chạy đúng; Versioning tốn chỗ; hạn ngắn chỉ dời lỗi sang người dùng mạng chậm.",
  "body": "<p><strong>Ví dụ chuyển giao: cùng một cơ chế, khác ràng buộc.</strong> Một ứng dụng chat cho phép gửi ảnh đại diện 2 MB. Ở đây quét nội dung gần như vô nghĩa — ảnh được tải lại và hiển thị qua một URL có hạn, nên rủi ro thật là người dùng A đọc được ảnh của người dùng B. Ràng buộc phải giữ là key có tiền tố tenant và mọi lần đọc đều qua một URL mới, không phải versioning. Ngược lại, một hệ thống hoá đơn cho phép đính kèm PDF 40 MB: ở đây chính nội dung là thứ nguy hiểm, nên trạng thái trung gian và bước quét mới là phần bắt buộc.</p><p><strong>Cùng một câu hỏi, ba mức trả lời.</strong> Câu hỏi luôn là: làm sao biết thứ trong bucket khớp với bản ghi. Mức thấp nhất là tin lời khai của client ở endpoint confirm, và mức này sai vì client có thể khai bất cứ thứ gì. Mức giữa là đọc <code>head_object</code> và so kích thước cùng content type, đúng cho phần lớn trường hợp và rất rẻ. Mức cao nhất là ghim <code>VersionId</code> ngay khi đọc, quét đúng version đó, và mọi lần phục vụ sau đều kèm <code>VersionId</code>, nên không có cửa sổ nào để ghi đè giữa lúc kiểm và lúc phục vụ.</p><p><strong>Dấu hiệu nhận ra bài toán này.</strong> Ba thứ đi cùng nhau: một endpoint cấp quyền chứ không nhận dữ liệu; một endpoint xác nhận chạy sau khi client đã tự làm xong việc; và một trạng thái trung gian trong bảng. Khi thấy cả ba, mọi câu hỏi về sau đều quy về một chỗ: thứ đang được phục vụ có đúng là thứ đã được kiểm không.</p><p><strong>Điều hay bị hỏi tiếp:</strong> vì sao không ký luôn kích thước vào URL? Vì với một PUT, kích thước nằm ở header do trình duyệt tự tính từ body, nên nó không phải ràng buộc mà người dùng thật có thể tuân theo. Muốn S3 tự chặn kích thước thì phải dùng presigned POST với điều kiện <code>content-length-range</code>, và đánh đổi là form phức tạp hơn. Và nếu bucket đã private thì có cần URL có hạn không? Có, vì private chỉ chặn người không có quyền; nó không giới hạn thời gian một người có quyền đọc được tệp.</p>",
  "code": "# API: cấp presigned URL, tự đặt key, ràng buộc header lúc ký.\n@app.post(\"/uploads/presign\")\nasync def presign(body: PresignIn, user=Depends(current_user)):\n    # 413 là quá dung lượng, 415 là sai media type. Hai lỗi khác nhau nên\n    # phải tách: gộp một mã thì client không biết sửa gì.\n    if body.size > MAX_BYTES:\n        raise HTTPException(413, \"tệp vượt hạn mức\")\n    if body.kind not in ALLOWED:\n        # ALLOWLIST nằm ngay ở bước cấp URL, không đợi bước xác nhận mới\n        # từ chối: lúc cấp URL chưa có byte nào, đây là nơi duy nhất còn\n        # quyết định được loại tệp nào được cấp quyền ghi.\n        raise HTTPException(415, \"loại tệp không được hỗ trợ\")\n    key = f\"{user.tenant}/{body.kind}/{uuid4().hex}{ext_of(body.kind)}\"\n    # client không được chọn key, chỉ được dùng key này\n    url = s3.generate_presigned_url(\n        ClientMethod=\"put_object\",\n        Params={\n            \"Bucket\": BUCKET, \"Key\": key,\n            \"ContentType\": body.content_type,   # S3 tự từ chối request sai header\n            # KHÔNG đưa kích thước vào đây: Content-Length là forbidden request\n            # header, trình duyệt tự tính từ body nên nó không phải một ràng buộc\n            # mà người dùng thật có thể tuân theo. Hạn mức kiểm thật ở bước confirm.\n        },\n        ExpiresIn=600,                          # 10 phút là đủ\n    )\n    # GHI bản ghi ngay lúc cấp URL, version_id sẽ được ghim ở bước confirm.\n    uploads.insert(version_id=None, key=key, tenant=user.tenant,\n                   kind=body.kind, state=\"PENDING\")\n    return {\"url\": url, \"key\": key, \"expires_in\": 600}\n\n# Worker: magic bytes + quét virus, cách ly trước khi công bố.\n# kind là loại ĐÃ KHAI ở bước cấp URL, đọc từ bản ghi upload chứ không phải\n# từ client: đây là chuẩn để đối chiếu, vì URL có thể bị dùng lại cho\n# tệp khác.\ndef confirm(object_key: str, tenant: str, kind: str) -> None:\n    head = s3.head_object(Bucket=BUCKET, Key=object_key)\n\n    # URL presigned DÙNG LẠI ĐƯỢC nhiều lần cho tới hết hạn (600s), nên sau\n    # khi worker quét xong, client vẫn PUT lại được và ghi đè chính key này.\n    # Nếu quét và phục vụ đều chỉ theo key, byte được quét và byte được phục\n    # vụ là hai đối tượng khác nhau. Versioning đóng đối tượng thành\n    # MỘT version bất biến.\n    version_id = head[\"VersionId\"]\n\n    if head[\"ContentLength\"] > MAX_BYTES:      # kích thước S3 thật sự ghi\n        s3.delete_object(Bucket=BUCKET, Key=object_key, VersionId=version_id)\n        raise ValueError(\"tệp lớn hơn mức client khai\")\n\n    # ContentType trong head chỉ là header client gửi lên, không phải nội dung\n    # thật. Muốn sniff magic bytes phải tải vài byte đầu của chính object,\n    # và phải kèm VersionId để đọc ĐÚNG version vừa ghim.\n    magic = s3.get_object(\n        Bucket=BUCKET, Key=object_key,\n        VersionId=version_id, Range=\"bytes=0-7\")[\"Body\"].read()\n    if not sniff(magic, kind):\n        quarantine(object_key, version_id)   # đổi sang prefix không đọc được\n        raise ValueError(\"nội dung không khớp loại đã khai\")\n\n    # Sniff đạt chỉ là bằng chứng sơ bộ về ĐỊNH DẠNG, không phải quét mã độc.\n    # Bản ghi lúc này ở SCANNING, chưa READY.\n    uploads.set(object_key, state=\"SCANNING\")\n    if scanner.scan(object_key, version_id) == \"infected\":\n        quarantine(object_key, version_id)\n        raise ValueError(\"bị chặn virus\")\n\n    publish(object_key, tenant, version_id)  # chỉ bản ghi READY mới được đọc\n\n\n# Phục vụ: LUÔN kèm VersionId đã qua quét. Bỏ VersionId thì S3 trả về\n# bản mới nhất của key, tức là có thể là bản client đã ghi đè sau khi quét.\ndef serve_url(object_key: str, tenant: str) -> str:\n    row = uploads.one(tenant=tenant, key=object_key)\n    if row.state != \"READY\":\n        raise HTTPException(409, \"bản ghi chưa READY\")\n    return s3.generate_presigned_url(\n        ClientMethod=\"get_object\",\n        Params={\"Bucket\": BUCKET, \"Key\": object_key,\n                \"VersionId\": row.version_id},   # bắt buộc: bản đã quét\n        ExpiresIn=300,\n    )\n\n# Vue: xin URL, PUT thẳng lên S3, rồi mới báo API.\nasync function upload(file, kind) {\n  const { url, key } = await api.post(\"/uploads/presign\", {\n    kind, size: file.size, content_type: file.type,\n  });\n  // PUT thẳng: byte không qua API của bạn. Content-Type phải bằng đúng\n  // giá trị đã ký vào URL, nếu khác S3 tự từ chối request này.\n  await http.put(url, file, { headers: { \"Content-Type\": file.type } });\n  return api.post(\"/uploads/confirm\", { key });\n}",
  "codeNote": "<p><strong>Giải phẫu từng khối lệnh trong Mẫu code chuẩn:</strong></p>\n<ul>\n <li><strong>Kiểm tra hạn mức và loại tệp ngay ở bước <code>POST /uploads/presign</code> (<code>413</code> vs <code>415</code>):</strong> Tách rõ mã lỗi <code>413 Payload Too Large</code> và <code>415 Unsupported Media Type</code> ngay từ khi chưa có byte nào được tải lên. Quan trọng nhất: Server <strong>tự sinh đường dẫn <code>key = f\"{user.tenant}/{body.kind}/{uuid4().hex}...\"</code></strong> chứ tuyệt đối không nhận tên file hay đường dẫn từ Client để chặn đứng lỗi ghi đè tệp của tổ chức khác (Path Traversal / Key Overwrite).</li>\n <li><strong>Ràng buộc <code>ContentType</code> trong <code>generate_presigned_url(..., Params={\"Bucket\":..., \"Key\":..., \"ContentType\": body.content_type})</code>:</strong> Khi đưa <code>ContentType</code> vào <code>Params</code> lúc ký, thuật toán <code>SigV4</code> đưa header <code>content-type</code> vào danh sách <code>X-Amz-SignedHeaders</code>. Lúc trình duyệt <code>PUT</code> file thẳng lên S3, nếu kẻ tấn công đổi <code>Content-Type</code> sang loại khác, chữ ký lập tức lệch và S3 từ chối thẳng với lỗi <code>403 SignatureDoesNotMatch</code>.</li>\n <li><strong>Ghim phiên bản bất biến <code>version_id = head[\"VersionId\"]</code> trong hàm <code>confirm()</code>:</strong> Vì một Presigned PUT URL có thể bị gọi lặp lại nhiều lần trong suốt 600 giây hiệu lực (kẻ tấn công tải ảnh sạch lên để vượt qua bước quét, rồi dùng lại chính URL đó <code>PUT</code> đè file mã độc lên cùng <code>key</code>), bật <strong>S3 Bucket Versioning</strong> và khóa chặt <code>version_id</code> ngay lúc kiểm tra giúp đảm bảo phiên bản được quét và phiên bản đem phục vụ là một đối tượng bất biến duy nhất.</li>\n <li><strong>Đọc 8 byte đầu (<code>Range=\"bytes=0-7\"</code>) kiểm tra <code>Magic Bytes</code> + Quét Virus:</strong> Không tin vào đuôi file <code>.png</code> hay header <code>Content-Type</code> do trình duyệt khai báo. Worker dùng <code>Range=\"bytes=0-7\"</code> tải đúng 8 byte đầu tiên của <code>version_id</code> đó để đối chiếu chữ ký nhị phân (ví dụ PNG phải bắt đầu bằng <code>89 50 4E 47</code>), sau đó quét mã độc xong mới chuyển trạng thái bản ghi từ <code>SCANNING</code> sang <code>READY</code>.</li>\n <li><strong>Phục vụ tệp luôn kèm <code>VersionId: row.version_id</code> trong <code>serve_url()</code>:</strong> Chỉ cấp URL đọc cho bản ghi đã <code>READY</code> và chỉ định rõ <code>VersionId</code> đã qua kiểm duyệt.</li>\n</ul>",
  "sayIt": ["Tệp đi bằng ba request nhẹ: xin presigned URL, PUT thẳng byte lên S3, rồi xác nhận để ghi metadata; byte không bao giờ đi qua API của tôi nên không tốn băng thông hai lần và không chạm trần body của gateway.","Key do server sinh chứ không nhận từ client, vì nếu lấy key từ client thì bất kỳ ai giữ token đều có thể chọn key trùng và ghi đè dữ liệu của tenant khác.","Content-Type thì ký được nên tôi ký vào URL để S3 tự từ chối request sai header, còn kích thước thì không ràng buộc được bằng chữ ký trong một PUT vì Content-Length là forbidden request header mà trình duyệt tự đặt, nên tôi kiểm ở bước xác nhận bằng head_object so với số client đã khai.","URL có hạn 10 phút vì tôi không thu hồi riêng từng URL được, dù vẫn chặn được bằng cách gỡ quyền của danh tính đã ký; bucket private cộng presigned nghĩa là biết tên tệp cũng không đọc được.","Loại tệp tôi chặn ngay ở bước cấp URL với lỗi 415, vì lúc cấp URL thì chưa có byte nào mà đó lại là chỗ duy nhất còn quyết định được loại nào được cấp quyền ghi. Ở bước xác nhận tôi sniff magic bytes bằng get_object kèm Range, nhưng so với đúng loại tôi đã khai chứ không chỉ thuộc danh sách cho phép; sniff đạt chỉ đưa bản ghi sang SCANNING, và chỉ bước quét nội dung riêng chạy bất đồng bộ mới chuyển sang READY, tức là cách ly trước khi công bố."],
  "qids": ["G06","E09","E07","G11"],
  "refs": ["aws-s3-presigned","aws-s3","aws-s3-versioning","mdn-http-headers"]
},
{
  "provenance": ["Số liệu trong sự cố, dòng thời gian và cách làm ngây thơ là giả định để dựng kịch bản, không phải số đo từ một hệ thống thật.","Các khẳng định về visibility timeout, receipt handle, redrive policy và về tính nguyên tử của transaction PostgreSQL được đối chiếu với tài liệu chính thức trong refs; phần còn lại là mô hình suy ra từ chúng."],
  "id": "L21",
  "stage": 4,
  "stageTitle": "Chặng 4 — Nối hai mảng",
  "title": "Outbox: vì sao ghi cơ sở dữ liệu và gửi message lệch nhau, và chỗ nào vá được",
  "goal": "Trong bài này bạn phải chỉ ra được hai cách mà một message trên hàng đợi có thể lệch khỏi hàng đã commit trong cơ sở dữ liệu, nói rõ outbox vá đúng cách nào trong hai cách đó, và giải thích vì sao outbox không cứu được cách còn lại.",
  "bridge": "Bài trước chốt rằng API chỉ cấp quyền ghi rồi xác nhận thứ đã nằm trong bucket, còn việc nặng chạy sau đó. Bài này lo phần “sau đó”: làm sao một hàng đã commit chắc chắn sinh ra một message, và làm sao một message chạy hai lần vẫn chỉ cho ra một kết quả.",
  "buildsOn": ["L06","L11"],
  "incident": "<p>Giả định đội vừa đẩy việc nặng sang worker: tải tệp 5 MB từ S3, quét nội dung, gửi hoá đơn. Visibility timeout để ở 30 giây vì đó là con số mặc định, trong khi thời gian xử lý p99 khoảng 45 giây vì tệp lớn cộng thêm một lượt gọi dịch vụ quét bên ngoài.</p><p>Một đợt 10.000 tệp đổ vào trong hai mươi phút, không có cảnh báo nào bắn. Đến chiều, kế toán mang một bảng tính: 340 khách nhận hai hoá đơn cho cùng một lần upload, và log worker có đúng hai dòng cho cùng một <code>message_id</code>, cách nhau 30 giây.</p><p>Dashboard vẫn xanh: số message hiển thị thấp, vì message đang xử lý nằm ở trạng thái ẩn. Chỉ số duy nhất xấu đi là độ tuổi của message cũ nhất, đã vượt 40 phút từ lúc nào không ai để ý.</p><p>Sau sự cố, hai thứ đổi: visibility timeout được đặt lại theo thời gian xử lý thật, và cảnh báo chuyển sang độ tuổi message thay vì số message.</p>",
  "askFirst": ["Vì sao một message có thể được hai worker cùng xử lý mà log không có dòng lỗi nào?","Vì sao số message trong hàng đợi trông thấp trong khi hệ thống đang tắc dần?","Nếu tăng số worker lên gấp ba, số hoá đơn gửi trùng sẽ tăng hay giảm?"],
  "predict": {"q":"Visibility timeout là 30 giây. Worker A nhận message ở giây 0, xử lý xong ở giây 45 và gọi xoá bằng receipt handle nhận được ở giây 0. Ở giây 30 message đã được giao cho worker B. Lời gọi xoá của A có hiệu lực không, và khách nhận mấy hoá đơn?","a":"<p>Lời gọi xoá của A không có hiệu lực trên bản đang thuộc B. <code>delete_message</code> xoá theo receipt handle của lần nhận, không theo <code>message_id</code>; khi lease hết hạn ở giây 30, phiếu nhận của A hết giá trị và B nhận một phiếu mới, nên lời gọi của A bị từ chối hoặc chỉ tác động lên một bản không còn tồn tại. Vì vậy B vẫn xử lý tiếp và khách nhận hai hoá đơn — trừ khi worker idempotent: nếu bước nghiệp vụ chèn khoá <code>message_id</code> trong cùng transaction, lần chạy của B đụng khoá và chỉ xác nhận rồi thoát, nên khách nhận đúng một hoá đơn. Nhánh còn lại: nếu A xoá trước khi lease hết thì B không bao giờ nhận, và trường hợp hai lần chạy không xảy ra — đó là lý do phải đặt visibility lớn hơn thời gian xử lý thay vì trông vào việc xoá.</p>"},
  "naive": "<p>Cách làm ngây thơ coi visibility timeout là khoá độc quyền, và coi message do hệ thống mình tạo ra là message không bao giờ hỏng.</p><ul><li><strong>Niềm tin:</strong> message đã bị ẩn khỏi hàng đợi thì không ai khác nhận được, nên xử lý xong chỉ cần xoá; và JSON do chính API ghi ra thì luôn parse được.</li><li><strong>Vì sao nghe hợp lý:</strong> ở mười message thử nghiệm, mỗi message chạy đúng một lần, không có hoá đơn trùng, và không có message nào hỏng định dạng.</li><li><strong>Chỗ chết:</strong> ẩn là một hợp đồng thuê có hạn chứ không phải khoá, nên khi lease hết mà worker còn đang chạy thì message hiện lại và worker khác nhận; và message hỏng định dạng thì hỏng ở mọi lần thử, nên để nó quay vòng chỉ đốt worker mà không bao giờ tới được hàng đợi lỗi.</li></ul>",
  "naiveCode": "import json\n\n# ❌ Cách làm sai phổ biến: queue tạo với VisibilityTimeout = 30 (giá trị mặc định).\n\ndef handle(raw: bytes, receipt: str) -> None:\n    # json.loads nằm NGOÀI try: JSON hỏng ném thẳng ra ngoài, không bao giờ chạm nhánh lỗi vĩnh viễn.\n    msg = json.loads(raw)\n\n    # Việc nặng mất khoảng 45 giây, trong khi visibility timeout chỉ 30 giây.\n    do_heavy_work(msg)\n\n    # Xoá sau khi xong, bằng receipt handle đã hết hạn ở giây thứ 30.\n    queue.delete_message(receipt)",
  "naiveOut": "<p>Ở mười message thử nghiệm mọi thứ đều đúng: mỗi message chạy một lần, không có hoá đơn trùng. Đó là lý do code được merge.</p><p> Ở 10.000 message trong đợt cao điểm, log worker có hai dòng cho cùng một <code>message_id</code> cách nhau đúng 30 giây, vì tới hạn visibility message hiện lại và worker khác nhận. Chiều hôm đó, 340 khách hàng nhận hai hoá đơn cho cùng một lần upload. </p><p> Đi kèm, một message JSON hỏng không bao giờ chạm nhánh lỗi vĩnh viễn: nó ném exception ngay ở dòng parse, worker báo lỗi, SQS đếm thêm một lần nhận, và message quay lại hàng đợi chờ vòng thử kế tiếp. Độ tuổi message cũ nhất vượt 40 phút trong khi số message hiển thị vẫn thấp, nên dashboard xanh hoàn toàn.</p>",
  "timeline": [["13:00:00","Đợt 10.000 tệp bắt đầu vào hàng đợi; độ tuổi message cũ nhất là 2 giây."],["13:00:05","Worker A nhận một message và bắt đầu tải tệp 5 MB."],["13:00:35","Visibility timeout 30 giây hết hạn; message hiện lại trong hàng đợi."],["13:00:36","Worker B nhận đúng message đó và bắt đầu cùng thao tác nghiệp vụ."],["13:01:20","Worker B xử lý xong và gửi hoá đơn thứ hai cho cùng một khách."],["14:30:00","Độ tuổi message cũ nhất là 41 phút trong khi số message hiển thị vẫn thấp."]],
  "rootCause": "<p>Hai nguyên nhân độc lập, và chỉ một trong hai được outbox vá.</p><ol><li>Visibility timeout là một hợp đồng thuê có hạn, không phải khoá: hết hạn mà worker chưa xoá thì message hiện lại và worker khác nhận. Vì vậy hệ thống giao ít nhất một lần, và chạy trùng là chuyện bình thường chứ không phải ngoại lệ.</li><li>Ghi cơ sở dữ liệu và gửi message là hai hệ thống riêng, không có transaction chung: commit xong mà gửi thất bại thì đơn không có message, gửi xong mà commit thất bại thì message trỏ tới một hàng không tồn tại. Đây là chỗ outbox vá.</li><li>Message hỏng định dạng bị đối xử như lỗi tạm thời, nên nó quay vòng cho tới hết hạn lưu trữ và không bao giờ tới được hàng đợi lỗi.</li></ol>",
  "concept": "Ghi cơ sở dữ liệu và gửi message là hai hệ thống không có transaction chung, nên outbox ghi message như hàng trong cùng transaction với nghiệp vụ rồi để một relay đẩy lên hàng đợi; outbox không cứu được việc giao trùng, nên worker phải idempotent.",
  "mechanism": "<ol><li><strong>Ghi nguyên tử:</strong> một transaction ghi cả hàng nghiệp vụ lẫn hàng outbox, rồi commit và trả 202 kèm mã việc. Commit thất bại thì không có gì được ghi, và cũng không có message nào để mồ côi.</li><li><strong>Relay đẩy lên hàng đợi:</strong> một tiến trình đọc các hàng outbox chưa gửi bằng <code>FOR UPDATE SKIP LOCKED</code> để nhiều relay chạy song song mà không tranh cùng một hàng, gửi lên hàng đợi, rồi đánh dấu đã gửi trong một transaction riêng. Gửi xong mà chết trước khi đánh dấu thì lần sau gửi lại — đó là lý do thứ hai khiến message có thể trùng.</li><li><strong>Worker xử lý và tự chặn trùng:</strong> worker chèn <code>message_id</code> vào bảng đã xử lý trong cùng transaction với việc nghiệp vụ; khoá chính làm trọng tài, nên hai worker chạy song song thì đúng một bên commit, bên kia nhận lỗi trùng khoá và chỉ xác nhận message.</li><li><strong>Tách lỗi tạm thời khỏi lỗi vĩnh viễn:</strong> lỗi hạ tầng thì gia hạn visibility để message quay lại sau; message hỏng định dạng thì chép sang hàng đợi lỗi rồi mới xoá bản gốc, vì xoá không tự chuyển message đi đâu cả.</li><li><strong>Hàng đợi lỗi có người đọc:</strong> redrive policy với số lần nhận tối đa đưa message độc sang hàng đợi lỗi, và cảnh báo khi độ sâu của nó khác 0 để có người thật xem.</li></ol>",
  "visuals": [{"id": "flow-outbox-worker", "question": "Vì sao một hàng đã commit có thể không có message, và vì sao một message có thể chạy hai lần — outbox vá chỗ nào?", "focus": "Outbox"}],
  "failureModes": "<p>Bốn kiểu hỏng của chính cách sửa này.</p><ul><li><strong>Bảng khoá phình không kiểm soát.</strong> Niềm tin sai: mỗi message một hàng khoá là rẻ. Nghe hợp lý vì một hàng chỉ vài chục byte. Điều đúng: số hàng bằng số message mãi mãi, nên cần TTL hoặc tiến trình dọn theo thời hạn. Phản chứng: thời gian chèn khoá tăng dần theo tuần dù lưu lượng không đổi, và bảng khoá lớn hơn bảng nghiệp vụ.</li><li><strong>Gia hạn visibility tưởng là cài một lần.</strong> Niềm tin sai: đã gia hạn thì message không hiện lại nữa. Nghe hợp lý vì lần gia hạn đó có tác dụng thật. Điều đúng: giá trị gia hạn chỉ có hiệu lực cho lần nhận hiện tại, nên logic phải chạy lại từ đầu ở mỗi lần nhận. Phản chứng: log có hai lần chạy cho cùng một message, cách nhau đúng bằng timeout gốc của hàng đợi.</li><li><strong>Message độc đốt worker.</strong> Niềm tin sai: cứ để nó thử lại, rồi nó sẽ tự vào hàng đợi lỗi. Nghe hợp lý vì hàng đợi có cơ chế redrive. Điều đúng: redrive chỉ hoạt động khi có redrive policy cùng số lần nhận tối đa; không cấu hình thì message quay lại cho tới hết hạn lưu trữ và chiếm worker suốt thời gian đó. Phản chứng: một message duy nhất chiếm một worker liên tục trong nhiều giờ, và số lần nhận của nó tăng đều.</li><li><strong>Hàng đợi lỗi thành thùng rác.</strong> Niềm tin sai: message đã vào hàng đợi lỗi là an toàn. Nghe hợp lý vì nó không còn quay vòng. Điều đúng: hàng đợi lỗi cũng có hạn lưu trữ, và không có cảnh báo khi độ sâu khác 0 thì message im lặng biến mất. Phản chứng: độ sâu hàng đợi lỗi về 0 mà không ai xử lý gì, và những đơn đó không bao giờ có kết quả.</li></ul>",
  "tradeoff": "<p><strong>Cái được.</strong> Một hàng đã commit chắc chắn sinh ra một message: không còn đơn đã trừ tiền mà không có hoá đơn, cũng không còn message trỏ tới hàng không tồn tại. Việc gửi trở thành một bước có thể thử lại, nên một lần hàng đợi không phản hồi không làm mất nghiệp vụ. Và vì worker tự chặn trùng ở tầng cơ sở dữ liệu, việc giao trùng trở thành chuyện vô hại thay vì chuyện phải đi đền khách.</p><p><strong>Cái mất.</strong> Thêm một bảng, một relay chạy liên tục, và một bảng khoá phải dọn. Độ trễ tăng: từ lúc commit tới lúc message lên hàng đợi có thêm một nhịp quét, nên nếu relay chạy mỗi phút thì mọi việc đều chậm thêm tới một phút. Visibility timeout dài cũng có giá ngược lại: worker chết thật thì message nằm ẩn lâu hơn trước khi được giao lại.</p><p><strong>Khi nào xứng đáng.</strong> Khi mất một message là mất tiền hoặc mất niềm tin của khách. Nếu việc chỉ là gửi thông báo trong ứng dụng và bỏ một cái cũng không sao, gửi thẳng sau commit đơn giản hơn nhiều.</p>",
  "alternatives": "<p><strong>Khi nào chọn cách khác.</strong></p><ul><li><strong>Gửi message sau commit, chấp nhận mất:</strong> chọn khi việc không quan trọng, ví dụ một thông báo đẩy. Cái giá là commit thành công mà gửi thất bại thì việc đó không bao giờ chạy, và không ai biết.</li><li><strong>Đọc thay đổi từ write-ahead log của cơ sở dữ liệu:</strong> chọn khi không muốn thêm bảng outbox và chấp nhận phụ thuộc vào một thành phần đọc log. Cái giá là thêm một hệ thống phải vận hành, và mô hình dữ liệu phải đủ đơn giản để suy ra message từ thay đổi hàng.</li><li><strong>Gọi trực tiếp worker qua một API nội bộ có thử lại:</strong> chọn khi khối lượng nhỏ và muốn thấy kết quả ngay. Cái giá là mất tính chịu lỗi: bên nhận chết thì bên gọi phải tự nhớ và thử lại, tức là tự viết lại một hàng đợi tồi hơn.</li><li><strong>Hàng đợi không hỗ trợ giao ít nhất một lần:</strong> gần như không tồn tại trong thực tế ở quy mô lớn, nên đừng thiết kế dựa trên giả định mỗi message chỉ tới đúng một lần.</li></ul>",
  "observe": "<p><strong>Bốn tín hiệu, và cái quan trọng nhất không phải cái mọi người nghĩ tới.</strong></p><ul><li><strong>Độ tuổi của message cũ nhất.</strong> Đây là chỉ số tắc thật: nó tăng ngay cả khi số message hiển thị thấp, vì message đang xử lý nằm ở trạng thái ẩn. Cảnh báo nên đặt trên chỉ số này, không phải trên số message.</li><li><strong>Bẫy của chính chỉ số đó.</strong> Message bị nhận lại quay về cuối hàng, nên độ tuổi cũ nhất có thể tụt xuống trong khi hệ thống vẫn hỏng; phải đọc kèm độ sâu hàng đợi lỗi mới không kết luận sớm rằng sự cố đã qua.</li><li><strong>Số message hiển thị đọc cùng số message đang ẩn.</strong> Hiển thị thấp cộng đang ẩn cao nghĩa là worker chạy hết công suất, không phải hàng đợi rảnh.</li><li><strong>Độ sâu hàng đợi lỗi.</strong> Cảnh báo khi khác 0, và phải có người thật xem, vì đó là nơi những đơn không có kết quả đang nằm chờ hết hạn lưu trữ.</li></ul>",
  "attacks": [{"q":"Bạn nói VisibilityTimeout của SQS phải lớn hơn thời gian xử lý của Worker. Vậy nếu tác vụ xử lý tệp có lúc mất 10 giây, có lúc mất 4 phút thì đặt VisibilityTimeout bao nhiêu?","a":"<p> <strong>Chốt:</strong> Đặt <code>VisibilityTimeout</code> cơ sở theo <strong>độ trễ đuôi <code>p99</code> cộng biên an toàn</strong> (hoặc tối thiểu gấp sáu lần thời gian timeout của hàm xử lý), kết hợp cơ chế <strong>Gia hạn nhịp tim chủ động (Visibility Heartbeat Extension)</strong> cho các tác vụ dài đột biến.</p>\n<ul>\n <li> <strong>Nhược điểm nếu đặt tĩnh quá dài (ví dụ 30 phút cho mọi bản tin):</strong> Nếu một worker bị crash ngay ở giây thứ 2 do lỗi mạng, bản tin đó sẽ bị ngâm ẩn suốt 30 phút mới được giao lại cho worker khác xử lý, làm độ trễ phục hồi khi có sự cố rất tệ.</li>\n <li> <strong>Cơ chế Heartbeat (Giống gia hạn hợp đồng thuê):</strong> Đặt <code>VisibilityTimeout</code> ban đầu ở mức hợp lý (ví dụ <code>60 giây</code>). Trong lúc worker đang xử lý tệp lớn, một luồng/coroutine phụ cứ mỗi <code>20 giây</code> kiểm tra nếu tác vụ chính vẫn đang chạy khỏe thì gọi <code>change_message_visibility(ReceiptHandle, VisibilityTimeout=60)</code> để xin thêm 60 giây nữa. Nếu worker chết thật, nhịp tim ngừng đập và bản tin được giao lại chỉ sau chưa đầy 1 phút! </li>\n</ul>"},{"q":"Tại sao trong log ghi rõ Worker thứ nhất đã gọi queue.delete_message() không báo lỗi gì, mà bản tin đó vẫn xuất hiện ở Worker thứ hai và chạy lặp lại?","a":"<p><strong>Chốt:</strong> Vì thời điểm Worker 1 hoàn thành công việc đã <strong>vượt quá <code>VisibilityTimeout</code></strong>, khiến bản tin được SQS giao cho Worker 2 kèm một mã <code>ReceiptHandle</code> mới trước khi Worker 1 kịp gọi xóa. </p>\n<ul>\n <li><strong>Cơ chế của <code>ReceiptHandle</code> trên SQS:</strong> <code>delete_message</code> không xóa theo <code>MessageId</code> mà xóa theo <strong>mã phiếu nhận của lần lấy đó (<code>ReceiptHandle</code>)</strong>. Ngay khi hết hạn <code>VisibilityTimeout</code> và Worker 2 nhận bản tin, phiếu <code>ReceiptHandle_1</code> của Worker 1 đã hết giá trị khóa độc quyền; trong khi đó Worker 2 đã bắt đầu chạy song song rồi! </li>\n <li><strong>Bài học cốt lõi:</strong> Trong hệ thống phân tán theo chuẩn <code>At-least-once Delivery</code>, <code>VisibilityTimeout</code> chỉ là một hợp đồng thuê có thời hạn (Lease), không phải khóa vĩnh viễn (Lock). Bạn <strong>không bao giờ được tin rằng <code>delete_message</code> sẽ ngăn được việc chạy trùng</strong> — sự đúng đắn bắt buộc phải nằm ở bảng khóa <code>processed_messages</code> trong cùng giao dịch Database của Worker.</li>\n</ul>"},{"q":"Triển khai bảng Transactional Outbox nghe phức tạp vì phải có tiến trình quét (Poller/Relay). Tại sao không cho API gửi thẳng sqs.send_message() trước rồi mới gọi db.commit() ngay dòng dưới cho đơn giản?","a":"<p><strong>Chốt:</strong> Gửi <code>sqs.send_message()</code> <em>trước</em> khi <code>db.commit()</code> tạo ra hai thảm họa đối lập: <strong>Bản tin ma (Phantom Message do Race Condition)</strong> và <strong>Bản tin mồ côi khi Commit thất bại</strong>.</p>\n<ul>\n <li> <strong>1. Lỗi chạy đua tốc độ (Race Condition trong vài mili-giây):</strong> SQS và Lambda Worker cực nhanh: ngay khi lệnh <code>sqs.send_message()</code> vừa trả về ở dòng 10, chỉ 15ms sau Worker đã nhận được bản tin và chạy câu lệnh <code>SELECT * FROM orders WHERE id =...</code> — trong khi ở tiến trình API, dòng 11 <code>db.commit()</code> vẫn đang chờ ghi đĩa WAL trên PostgreSQL và chưa hoàn tất!</li><li>Worker truy vấn không thấy đơn hàng đâu nên báo lỗi.</li>\n <li><strong>2. Lỗi Rollback ở phút chót:</strong> Nếu <code>sqs.send_message()</code> đã bay đi thành công, nhưng ngay dòng dưới lệnh <code>db.commit()</code> bị lỗi (rớt kết nối DB hoặc vi phạm ràng buộc khóa ngoại <code>DEFERRABLE</code>), đơn hàng bị hủy trong DB nhưng Worker vẫn gửi hóa đơn và trừ kho cho một đơn hàng không hề tồn tại! Chỉ có <code>Transactional Outbox</code> (ghi cùng 1 Transaction ACID vào PostgreSQL rồi mới đẩy sang SQS) mới đảm bảo tính nhất quán tuyệt đối. </li>\n</ul>"},{"q":"Ở trong Worker, thay vì dùng INSERT INTO processed_messages bắt lỗi trùng khóa chính, tôi viết câu lệnh SELECT kiểm tra xem đã xử lý chưa rồi mới chạy (if not exists -> process) có được không?","a":"<p><strong>Chốt:</strong> <strong>Tuyệt đối không!</strong> Mô hình đọc kiểm tra trước rồi mới hành động (<code>Check-Then-Act</code> bằng <code>SELECT</code> thường) bị <strong>thủng hoàn toàn khi có 2 Worker chạy song song </strong>.</p>\n<ul>\n <li> <strong>Kịch bản thủng (Race Condition):</strong> Ở mức cô lập mặc định <code>READ COMMITTED</code> của PostgreSQL, khi 2 bản sao của cùng một bản tin đến 2 Worker cùng lúc (hoặc Worker 1 bị treo mạng rồi tỉnh dậy đúng lúc Worker 2 vừa nhận), cả Worker 1 và Worker 2 cùng chạy <code>SELECT 1 FROM processed_messages WHERE id = 'M1'</code> tại mili-giây thứ 0. Cả hai đều nhận kết quả là <code>0 dòng</code> (chưa có)! Thế là cả hai cùng bước vào hàm trừ tiền và xuất hóa đơn hai lần!</li>\n <li><strong>Cách khóa nguyên tử duy nhất (Atomic DB Constraint):</strong> Để chính chỉ mục khóa chính (<code>PRIMARY KEY</code> / <code>UNIQUE CONSTRAINT</code>) của PostgreSQL làm trọng tài trong cùng một Transaction: lệnh <code>INSERT INTO processed_messages (id) VALUES ('M1')</code> tự động khóa ở mức hàng trong B-Tree Index — nếu 2 Worker cùng chạy, PostgreSQL cho đúng 1 Worker đi tiếp và bắt Worker thứ 2 chờ kết quả commit của Worker 1 rồi ném ngay ngoại lệ <code>UniqueViolation</code>.</li>\n</ul>"}],
  "anchor": "Số message nói bạn đang bận, độ tuổi message nói bạn đang tắc.",
  "say30": "SQS giao ít nhất một lần, nên cùng một message có thể chạy hai lần và worker phải idempotent. Tôi ghi outbox cùng transaction với nghiệp vụ, rồi một relay đẩy lên bằng FOR UPDATE SKIP LOCKED. Chống chạy trùng bằng khoá chính chèn cùng transaction, không đọc trước rồi ghi sau. Visibility timeout là lease nên tôi đặt theo p99 và gia hạn định kỳ; để 30 giây trong khi xử lý 45 giây là 340 khách nhận hai hoá đơn.",
  "say90": "[Nêu vấn đề (30s)]: Gửi message không nằm trong transaction PostgreSQL nên có hai chỗ lệch: commit xong mà gửi thất bại thì đơn đã trừ tiền không có hoá đơn, gửi xong mà commit thất bại thì message trỏ tới hàng không tồn tại. Hàng đợi lại giao ít nhất một lần, nên một việc có thể chạy hai lần: 340 khách nhận hai hoá đơn vì visibility 30 giây ngắn hơn xử lý 45 giây.\n\n[Cơ chế (45s)]: Outbox ghi hàng nghiệp vụ và hàng message trong cùng một transaction, nên cả hai cùng có hoặc cùng không. Một relay đọc các hàng chưa gửi bằng FOR UPDATE SKIP LOCKED rồi đẩy lên và đánh dấu đã gửi; gửi xong mà chết trước khi đánh dấu thì lần sau gửi lại, nên vẫn trùng. Vì vậy worker chèn message_id vào bảng đã xử lý trong cùng transaction, để khoá chính làm trọng tài khi hai worker chạy song song. Visibility timeout đặt theo p99 và gia hạn.\n\n[Ranh giới (15s)]: Outbox không cứu được việc giao trùng và không cho thứ tự; nó thêm một bảng, một relay liên tục và một bảng khoá phải dọn, còn hàng đợi lỗi vẫn cần người đọc.",
  "body": "<p><strong>Kịch bản Use-case thực chiến trong phỏng vấn:</strong></p><ul><li> <strong>Bài toán gặp phải:</strong> Hệ thống xuất hóa đơn sau thanh toán với đỉnh 200 đơn mỗi phút. FastAPI commit đơn rồi gọi sqs.send_message ngay, nên khi mạng chập chờn có 19 đơn đã trừ tiền nhưng không bao giờ có hóa đơn. Worker xử lý 45 giây nhưng visibility để mặc định 30 giây, nên 340 khách nhận hai hóa đơn. </li><li><strong>Cách áp dụng Pattern của bài này để giải:</strong> Ghi outbox cùng transaction với đơn, relay đẩy lên SQS bằng SKIP LOCKED. Đặt visibility theo p99 cộng biên an toàn, chèn khóa message_id trong transaction nghiệp vụ, và gửi message JSON hỏng sang DLQ. </li><li><strong>Vì sao chọn cách này:</strong> Gửi trước rồi commit sau tạo ra message ma khi race condition. Outbox đổi việc gửi thành một bước có thể thử lại, nên không mất message.</li></ul><p><strong>Công thức suy luận nhanh khi bị hỏi xoáy (Dấu hiệu -&gt; Phản xạ):</strong></p><ul><li><strong>Dấu hiệu: cùng một message_id xuất hiện hai lần cách nhau đúng bằng visibility timeout:</strong> Message hiện lại vì lease hết hạn. Phản xạ: tăng visibility theo p99 hoặc gia hạn, và kiểm khóa chống trùng. </li><li><strong>Dấu hiệu: đơn đã commit nhưng không có message:</strong> Gửi SQS nằm ngoài transaction. Phản xạ: đưa việc gửi qua outbox và relay.</li><li><strong>Dấu hiệu: số message hiển thị thấp nhưng độ tuổi message cũ nhất tăng:</strong> Message đang ở trạng thái ẩn hoặc quay vòng lỗi. Phản xạ: cảnh báo theo độ tuổi message cũ nhất và kiểm độ sâu hàng đợi lỗi.</li></ul>",
  "code": "# ✅ Cách làm chuẩn: worker idempotent, tách lỗi tạm thời và lỗi vĩnh viễn.\ndef handle(raw: bytes, receipt: str) -> None:\n    # 1. Parse JSON trong try RIÊNG: JSON hỏng là lỗi vĩnh viễn, phải vào DLQ trước khi xoá bản gốc.\n    try:\n        msg = json.loads(raw)\n    except json.JSONDecodeError:\n        dlq.send_message(MessageBody=raw.decode())\n        queue.delete_message(ReceiptHandle=receipt)\n        return\n\n    # 2. Khoá nghiệp vụ nằm TRONG CÙNG transaction với việc nghiệp vụ.\n    try:\n        with db.atomic() as c:\n            c.execute(\"INSERT INTO processed_messages (id) VALUES (%s)\",\n                      (msg[\"message_id\"],))         # trùng khoá chính = đã xử lý\n            do_heavy_work(c, msg)\n    except UniqueViolation:\n        # Lần chạy trước đã commit xong: đây là lần giao thừa, xác nhận rồi thôi.\n        queue.delete_message(ReceiptHandle=receipt)\n        return\n    except TransientError:\n        # Lỗi hạ tầng: gia hạn visibility để message quay lại đúng lúc.\n        queue.change_message_visibility(ReceiptHandle=receipt, VisibilityTimeout=120)\n        raise\n\n    queue.delete_message(ReceiptHandle=receipt)      # chỉ xoá khi đã thành công",
  "codeNote": "<p><strong>Giải phẫu từng khối lệnh trong Mẫu code chuẩn:</strong></p>\n<ul>\n <li><strong>Bước 1 - Tách riêng khối <code>try: msg = json.loads(raw)</code> ở đầu hàm:</strong> Nếu bản tin bị hỏng định dạng JSON (Poison Pill / Malformed Message), việc để <code>worker</code> ném ngoại lệ ra ngoài để SQS thử lại 5 lần là hoàn toàn vô ích vì chuỗi hỏng thì thử 100 lần vẫn hỏng. Mẫu code bắt riêng <code>json.JSONDecodeError</code>, chủ động chép nguyên bản sang <code>DLQ</code> để điều tra rồi gọi <code>delete_message</code> giải phóng hàng đợi ngay lập tức.</li>\n <li><strong>Bước 2 - Khóa chống trùng (Idempotency) nằm TRONG CÙNG giao dịch DB với nghiệp vụ (<code>with db.atomic() as c:</code>):</strong> Câu lệnh <code>INSERT INTO processed_messages (id) VALUES (%s)</code> và hàm <code>do_heavy_work(c, msg)</code> nằm chung trong một Transaction ACID của PostgreSQL. Nếu <code>do_heavy_work</code> bị lỗi giữa chừng, cả lệnh <code>INSERT</code> khóa cũng được <code>ROLLBACK</code> tự động để lần thử lại sau vẫn chạy được; ngược lại nếu đã <code>COMMIT</code> xong mà worker rớt mạng trước khi kịp gọi <code>delete_message</code>, lần giao lại (Redelivery) thứ hai sẽ đụng ngay lỗi trùng khóa chính <code>UniqueViolation</code>.</li>\n <li><strong>Nhánh <code>except UniqueViolation: queue.delete_message(...)</code>:</strong> Khi cơ sở dữ liệu báo khóa <code>message_id</code> đã tồn tại (tức là lần chạy trước đã thực thi và commit nghiệp vụ thành công), worker không làm lại việc nặng nữa mà chỉ xác nhận xóa bản tin khỏi SQS rồi kết thúc êm đẹp.</li>\n <li><strong>Nhánh <code>except TransientError: queue.change_message_visibility(..., VisibilityTimeout=120)</code>:</strong> Khi gặp lỗi hạ tầng tạm thời (đối tác quá tải), worker chủ động đặt khoảng chờ ẩn (Backoff) rồi <code>raise</code> để SQS giữ bản tin lại cho lượt thử kế tiếp.</li>\n</ul>",
  "sayIt": ["Gửi message SQS và commit PostgreSQL là hai hành động riêng, không cùng transaction; tôi chọn outbox khi việc không được phép mất, chọn gửi trước rồi commit khi việc chạy lại được vô hại.","Outbox là chèn hàng trong cùng transaction với hàng nghiệp vụ, một tiến trình quét bằng FOR UPDATE SKIP LOCKED đẩy lên SQS, và toàn bộ quét phải nằm trong transaction vì khoá chỉ giữ trong transaction.","SQS bảo đảm ít nhất một lần nên worker phải idempotent; tôi chống chạy trùng bằng chèn khoá processed_messages trong cùng transaction với việc nghiệp vụ, không bằng đọc trước rồi ghi sau.","Visibility timeout là lease chứ không phải lock; tôi đặt theo p99 thời gian xử lý cộng biên an toàn và gia hạn định kỳ, vì để 30 giây trong khi xử lý 45 giây thì message hiện lại và worker khác nhận cùng một việc.","Lỗi tạm thời tôi gia hạn visibility để message quay lại; lỗi vĩnh viễn như JSON hỏng tôi parse trong try riêng, gửi một bản sang DLQ rồi mới xoá, vì xoá không tự chuyển message sang DLQ và DLQ chỉ hoạt động khi queue có redrive policy với maxReceiveCount.","Phía client cập nhật trạng thái bằng polling hoặc SSE, và tôi cảnh báo trên độ tuổi message cũ nhất chứ không phải số message, vì số message thấp chỉ là worker đang chạy hết công suất, không phải hệ thống ổn."],
  "qids": ["E07","G10","G11","F09"],
  "refs": ["aws-sqs-visibility","aws-sqs-dlq","pg-transactions","pg-upsert"]
},
{
  "provenance": ["Số liệu trong sự cố, dòng thời gian và cách làm ngây thơ là giả định để dựng kịch bản, không phải số đo từ một hệ thống thật.","Các khẳng định về Cache-Control, immutable, Origin Access Control, Block Public Access và OIDC được đối chiếu với tài liệu chính thức trong refs; phần còn lại là mô hình suy ra từ chúng."],
  "id": "L22",
  "stage": 4,
  "stageTitle": "Chặng 4 — Nối hai mảng",
  "title": "Deploy: vì sao index.html cũ trỏ vào tệp JS đã xoá, và rollback đúng phải là gì",
  "goal": "Trong bài này bạn phải giải thích được vì sao một người dùng đang mở trang lại nhận màn hình trắng ngay sau một lần deploy sạch, bằng cách chỉ ra hai chính sách cache khác nhau cho hai loại tệp, và nói được hai thứ phải có sẵn trước khi deploy để rollback chỉ còn là một thao tác đổi con trỏ.",
  "bridge": "Bài trước chốt rằng việc nặng chạy sau khi commit, và cái giá của nó là một bảng phải dọn. Bài này đưa cả hệ thống đó ra production: một lần deploy đổi cả giao diện lẫn cấu trúc bảng, nên câu hỏi không còn là code đúng hay sai, mà là người dùng đang cầm bản cũ sẽ gặp gì và bạn lùi lại trong bao lâu.",
  "buildsOn": ["L18","L19","L20","L21"],
  "incident": "<p>Giả định đội deploy bản 2.0 lúc 22 giờ. Bản build gồm một <code>index.html</code> và vài tệp JS có hash trong tên; tất cả được đẩy lên cùng một bucket S3, phục vụ qua CloudFront, và bucket đặt đúng một chính sách cache 24 giờ cho mọi tệp vì như thế là đỡ phải nghĩ.</p><p>22:04, pipeline chạy <code>aws s3 sync dist/ s3://... --delete</code>. Tệp JS của bản 1.9 bị xoá khỏi bucket ngay lập tức. Người dùng nào đã tải trang trong 24 giờ trước đó vẫn còn <code>index.html</code> cũ trong máy, và tệp đó trỏ tới JS vừa bị xoá: họ nhận 404 rồi màn hình trắng. Sáng hôm sau khoảng 8% người dùng vào trang báo lỗi, trong khi máy của đội mở trình duyệt ẩn danh vẫn thấy trang lên bình thường.</p><p>Đội thử lùi lại bằng cách revert commit rồi cho pipeline build lại. Bản dựng ra hash khác, một thư viện phụ thuộc vừa lên bản mới nên kết quả không giống bản 1.9 đã chạy tuần trước; mất 40 phút, và trong suốt thời gian đó nhóm người dùng kia vẫn thấy trang trắng.</p><p>Buổi kiểm tra bảo mật sau đó chỉ ra thêm một chuyện: bucket cho phép đọc công khai, nên ai biết tên bucket cũng tải được mọi tệp trực tiếp qua URL S3, bỏ qua CloudFront.</p>",
  "askFirst": ["Vì sao người dùng đã tải trang từ hôm trước lại thấy màn hình trắng, trong khi máy của bạn mở trang vẫn bình thường?","Điều gì có thể khiến một bản build lại từ đúng commit cũ vẫn không giống bản đã chạy tuần trước?","Vì sao một bucket không cho ai truy cập vẫn phục vụ được trang cho cả internet, và thứ gì đứng ra bảo lãnh cho việc đó?"],
  "predict": {"q":"Chính sách cache đã đặt đúng: tệp có hash là <code>max-age=31536000, immutable</code>, còn <code>index.html</code> là <code>no-cache</code>. Pipeline đẩy asset trước rồi mới đẩy index. Một người dùng đã mở tab từ trước bấm tải lại. Trình duyệt lấy <code>index.html</code> từ đâu, và còn nhánh nào khiến trang vẫn trắng dù chính sách đúng?","a":"<p>Trình duyệt gửi điều kiện <code>If-None-Match</code> vì index.html là no-cache: nội dung chưa đổi thì nhận 304 và dùng bản đã lưu, còn vừa promote thì nhận 200 với index mới. Vì index mới chỉ trỏ tới tệp có hash đã lên từ trước, trang lên bình thường — đây là nhánh chính. Nhánh xấu vẫn còn: nếu pipeline đẩy index trước khi asset lên xong, hoặc có bước xoá asset của bản cũ, thì index mới trỏ vào tệp chưa có và người dùng nhận 404, nghĩa là no-cache chỉ cứu được khi thứ tự đẩy đúng và asset cũ không bị xoá. Nhánh thứ ba: tab đang mở vẫn chạy JS cũ và gọi một route mà bản mới đã đổi; ở đây không có màn hình trắng, chỉ có lỗi API, vì JS cũ vẫn nằm trong bộ nhớ tab.</p>"},
  "naive": "<p>Cách làm ngây thơ coi mọi tệp của một bản build là cùng loại, và coi bản build là thứ có thể dựng lại bất cứ lúc nào.</p><ul><li><strong>Niềm tin:</strong> cả bucket dùng một chính sách cache là đủ, và muốn lùi lại thì revert commit rồi build lại.</li><li><strong>Vì sao nghe hợp lý:</strong> trên máy đội, mở tab mới thì trang luôn lên đúng bản mới nhất, và build lại từ commit cũ cho ra bản chạy được — cả hai đều đúng.</li><li><strong>Chỗ chết:</strong> <code>index.html</code> là tệp duy nhất không có hash trong tên, nên nó bị cache y như tệp có hash và trỏ vào tệp JS mà bước <code>--delete</code> vừa xoá; còn build lại phụ thuộc vào registry và phiên bản thư viện tại thời điểm build, nên nó không tái tạo đúng bản đã chạy.</li></ul>",
  "naiveCode": "// ❌ Cách làm sai phổ biến: bucket public, cache đồng nhất, deploy bằng tay.\n// 1. Bucket policy cho Principal * và action s3:GetObject:\n//    CloudFront đọc được, nhưng Internet cũng đọc trực tiếp được qua URL S3.\n// 2. Cache-Control mặc định cho mọi file:\n//    index.html sống một ngày cùng TTL với app.a1b2c3.js, nên HTML cũ trỏ vào JS đã xoá.\n// 3. Deploy bằng tay, không đánh số artifact:\n//    rollback thành đoán file nào thuộc bản cũ.",
  "naiveOut": "Ngày đầu mọi thứ xanh vì đội luôn mở tab mới, và bản build nào cũng chạy được trên máy mình. Sau đợt deploy thứ hai, một bộ phận người dùng cầm index.html cache một ngày tải trang trắng, vì tệp JS mà nó trỏ tới đã bị bước --delete xoá. Kiểm tra bảo mật phát hiện tệp trong bucket đọc được trực tiếp qua URL S3 vì bucket mở public. Khi cần lùi lại, pipeline build lại từ commit cũ nhưng ra hash khác và kéo theo một thư viện vừa lên bản mới, nên mất bốn mươi phút mới có bản chạy được.",
  "timeline": [["22:00","Pipeline đẩy toàn bộ thư mục dist lên bucket, và bucket áp một chính sách cache 24 giờ cho mọi tệp."],["22:04","Bước <code>--delete</code> xoá tệp JS của bản 1.9 khỏi bucket."],["22:05","Người dùng còn giữ <code>index.html</code> cũ tải lại trang và nhận 404 cho tệp JS vừa bị xoá."],["08:30","Khoảng 8% người dùng vào trang báo màn hình trắng trong buổi sáng."],["09:10","Đội revert commit và cho pipeline build lại; bản dựng ra hash khác và kéo theo một thư viện vừa lên bản mới."],["09:50","Bản chạy được sau 40 phút, lâu hơn nhiều so với việc trỏ lại một artifact đã có sẵn."]],
  "rootCause": "<p>Ba nguyên nhân độc lập, mỗi cái sửa được riêng.</p><ol><li><strong>Hai loại tệp bị áp một chính sách cache.</strong> Tệp có hash trong tên không bao giờ đổi nội dung, nên cache lâu là đúng. <code>index.html</code> không có hash và nội dung đổi mỗi lần deploy, nên nếu nó bị cache thì trình duyệt dùng bản cũ và trỏ tới tệp JS mà bước <code>--delete</code> đã xoá.</li><li><strong>Bản deploy không phải một artifact bất biến.</strong> Ghi đè tại chỗ khiến bản cũ biến mất, nên lùi lại phải dựng lại từ mã nguồn; mà dựng lại phụ thuộc registry và phiên bản thư viện ở thời điểm build, nên nó không tái tạo đúng bản đã chạy.</li><li><strong>Bucket mở công khai để CloudFront đọc được.</strong> Đó là cách nhanh nhất và cũng là cách bỏ qua mọi luật đặt trước CloudFront, vì bất kỳ ai biết tên bucket đều gọi thẳng S3.</li></ol>",
  "concept": "Tệp có hash trong tên không đổi nội dung nên cache lâu là đúng, còn index.html không có hash nên phải no-cache để mỗi lần mở trang đều hỏi lại; và mỗi bản build phải là một artifact bất biến để rollback chỉ là đổi con trỏ, không phải build lại.",
  "mechanism": "<ol><li><strong>Migration tương thích ngược đi trước:</strong> thêm cột mới và để code đọc được cả hai dạng trước khi deploy code mới; cột cũ chỉ bị xoá ở chu kỳ sau. Nhờ vậy bản cũ và bản mới cùng chạy được trong lúc chuyển, và rollback không vấp vào cấu trúc bảng.</li><li><strong>Đẩy tệp có hash trước:</strong> CI lấy quyền tạm thời qua OIDC thay vì lưu access key dài hạn, build ra <code>dist</code>, rồi đẩy thư mục asset lên bucket private với <code>max-age=31536000, immutable</code> và tuyệt đối không dùng <code>--delete</code>. Tệp của bản cũ phải còn, vì người dùng đang mở tab cũ vẫn cần chúng.</li><li><strong>Đẩy <code>index.html</code> sau cùng:</strong> chỉ khi mọi tệp mới đã nằm trên bucket mới chép <code>index.html</code> vào gốc với <code>no-cache</code>, rồi invalidate đúng đường dẫn đó. Thứ tự này là thứ khiến không ai bị trỏ tới một tệp chưa tồn tại.</li><li><strong>Đóng đường vòng qua S3:</strong> bucket để private, bật Block Public Access, và cho CloudFront ký yêu cầu tới S3 bằng OAC. Trình duyệt chỉ nói chuyện với CloudFront, nên mọi luật đặt trước nó vẫn có hiệu lực.</li><li><strong>Rollback là một thao tác chép tệp:</strong> chép <code>index.html</code> của release cũ ra gốc bucket rồi invalidate, mất vài giây, vì asset của bản cũ vẫn còn nguyên trên bucket. Không build lại, không chờ registry.</li></ol>",
  "visuals": [{"id": "flow-deploy-cache", "question": "Vì sao index.html phải no-cache trong khi tệp JS có hash lại cache một năm, và rollback đi qua những bước nào?", "focus": "index.html: no-cache"}],
  "failureModes": "<p>Bốn kiểu hỏng của chính cách deploy này.</p><ul><li><strong>index.html lại bị cache.</strong> Niềm tin sai: đã khai <code>no-cache</code> trong pipeline là xong. Nghe hợp lý vì header có thật trong lệnh <code>s3 cp</code>. Điều đúng: giá trị cache hiệu lực là giá trị đi kèm object tại thời điểm ghi, nên một lần đẩy tay hoặc một luật cache mặc định ở CloudFront là header trong pipeline bị ghi đè. Phản chứng: sau deploy, người dùng vẫn thấy bản cũ cho tới khi xoá cache trình duyệt.</li><li><strong>Asset cũ bị xoá bởi thao tác dọn.</strong> Niềm tin sai: giữ asset cũ là rác, dọn cho gọn. Nghe hợp lý vì bucket sạch thì dễ nhìn. Điều đúng: tab đang mở của người dùng vẫn cần tệp của bản cũ, nên chỉ được dọn sau khi không còn bản nào trỏ tới. Phản chứng: tỉ lệ 404 trên asset tăng trong vài giờ sau mỗi lần dọn, đúng ở nhóm người dùng mở tab lâu.</li><li><strong>Rollback không tái tạo đúng bản cũ.</strong> Niềm tin sai: revert commit rồi build lại là quay về đúng trạng thái trước. Nghe hợp lý vì mã nguồn thì không đổi. Điều đúng: registry và phiên bản thư viện ở thời điểm build đã khác, nên bản dựng ra không giống bản đã chạy. Phản chứng: sau rollback, lỗi cũ không tái hiện, hoặc một lỗi mới xuất hiện chỉ ở bản vừa dựng lại.</li><li><strong>Migration không tương thích ngược.</strong> Niềm tin sai: deploy code và chạy migration cùng lúc là một bước. Nghe hợp lý vì trong môi trường dev mọi thứ đổi cùng nhau. Điều đúng: trong lúc chuyển, bản cũ và bản mới cùng chạy, nên migration xoá cột mà bản cũ còn đọc là bản cũ chết ngay, và rollback cũng không cứu được. Phản chứng: lỗi 500 xuất hiện rải rác trong vài phút deploy rồi tự hết khi mọi instance đã lên bản mới.</li></ul>",
  "tradeoff": "<p><strong>Cái được.</strong> Người dùng đang mở tab không còn nhận màn hình trắng, vì <code>index.html</code> luôn được hỏi lại và tệp có hash không bao giờ bị thay nội dung. Rollback trở thành một thao tác vài giây thay vì một cuộc dựng lại có thể thất bại đúng lúc cần nhất. Và vì bucket đóng, mọi request đều đi qua CloudFront, nên luật chặn và giới hạn tốc độ đặt ở đó mới thật sự có tác dụng.</p><p><strong>Cái mất.</strong> Mỗi bản build để lại một bộ tệp phải giữ và một chính sách dọn phải viết đúng; hai chính sách cache khác nhau là hai chỗ có thể cấu hình sai, và sai ở <code>index.html</code> thì hậu quả nặng hơn. Thêm một bước invalidate sau mỗi lần promote, và migration phải chia thành nhiều lần chạy thay vì một lần.</p><p><strong>Khi nào xứng đáng.</strong> Gần như luôn luôn, vì cái giá là vài dòng cấu hình còn cái mất là người dùng thấy trang trắng ngay sau một lần deploy đúng. Chỉ khi trang là bản thử nghiệm không có người dùng thật thì thứ tự đẩy và chính sách cache mới không đáng bận tâm.</p>",
  "alternatives": "<p><strong>Khi nào chọn cách khác.</strong></p><ul><li><strong>Nền tảng hosting tĩnh có CDN tích hợp:</strong> chọn khi frontend đơn giản và đội không muốn tự quản lý bucket, OAC và invalidate. Cái giá là ít quyền kiểm soát header và luật ở biên hơn, và khó giữ chung một cách vận hành với phần còn lại của hệ thống.</li><li><strong>Phục vụ <code>index.html</code> từ chính API thay vì từ CDN:</strong> chọn khi cần render phía server để nhét cấu hình theo từng người dùng. Cái giá là mỗi lần mở trang đều chạm vào backend, và tầng đó trở thành đường găng của việc tải trang.</li><li><strong>Giữ nguyên một bản duy nhất và chấp nhận trắng trang khi deploy sai:</strong> chỉ hợp lý với hệ thống nội bộ ít người dùng. Cái giá là mỗi lần deploy hỏng đều là một sự cố thật, và không có đường lùi nào ngoài sửa tay.</li></ul>",
  "observe": "<p>Bốn tín hiệu, mỗi tín hiệu theo dõi một quyết định.</p><ul><li><strong>Tỉ lệ 404 trên đường dẫn asset.</strong> Tăng ngay sau deploy nghĩa là có <code>index.html</code> cũ đang trỏ tới tệp đã bị xoá; đây là tín hiệu sớm nhất và cũng là tín hiệu duy nhất người dùng cảm nhận được trước khi họ báo.</li><li><strong>Tỉ lệ phản hồi 200 so với 304 cho <code>index.html</code>.</strong> Gần như toàn 200 nghĩa là mỗi lần mở trang đều tải lại toàn bộ tệp, tức là <code>no-cache</code> đã bị đổi thành <code>no-store</code>; gần như toàn 304 và không có 200 nào sau deploy nghĩa là header không được áp dụng.</li><li><strong>Phiên bản đang phục vụ ở biên so với artifact mong muốn.</strong> Trả một header chứa mã bản build rồi so sau mỗi lần promote; lệch nghĩa là invalidate chưa lan tới mọi điểm biên.</li><li><strong>Thời gian từ promote tới khi mọi điểm biên phục vụ bản mới.</strong> Đây là con số quyết định bạn dám rollback nhanh tới đâu, vì rollback cũng đi qua đúng con đường đó.</li></ul>",
  "attacks": [{"q":"Vite đã gắn mã hash vào tên mọi file JS và CSS rồi, vậy tại sao file index.html ở gốc bucket lại bắt buộc phải đặt Cache-Control: no-cache mà không được cache lâu?","a":"<p><strong>Chốt:</strong> Vì chính cái tên <code>index.html</code> <strong>không hề có mã hash</strong> — nó là \"tấm bản đồ gốc\" chứa đường dẫn trỏ tới các tên file JS/CSS có mã hash của từng bản phát hành.</p>\n<ul>\n <li> <strong>Hậu quả nếu cache lâu <code>index.html</code> (ví dụ <code>max-age=86400</code>):</strong> Khi bạn deploy bản mới lúc 10h sáng, các máy khách đã từng vào web lúc 9h sáng sẽ tiếp tục lấy file <code>index.html</code> cũ từ bộ nhớ đệm đĩa của trình duyệt suốt 24 tiếng tiếp theo mà không hề hỏi lại CloudFront. Họ bị kẹt ở giao diện cũ (gọi lên API Backend mới đã đổi logic), hoặc tệ hơn: nếu bạn lỡ xóa chunk JS cũ trên S3, file <code>index.html</code> cũ sẽ gọi vào file JS đã bị xóa và gây <strong>màn hình trắng toàn tập (White Screen of Death)</strong>!</li>\n <li> <strong>Ý nghĩa thật của <code>Cache-Control: no-cache</code>:</strong> <code>no-cache</code> không có nghĩa là \"cấm lưu cache\", mà có nghĩa là <strong>\"Được lưu bản sao trên trình duyệt, nhưng mỗi lần mở trang phải gửi thẻ <code>If-None-Match: ETag</code> lên CloudFront để hỏi xem có bản mới chưa\"</strong>. Nếu chưa deploy mới, CloudFront trả <code>304 Not Modified</code> (0 byte body, cực nhanh); nếu vừa deploy xong, CloudFront trả ngay <code>index.html</code> mới tinh!</li>\n</ul>"},{"q":"Tại sao phải cấu hình CloudFront Origin Access Control (OAC) phức tạp mà không bật Public Read cho S3 Bucket chứa web và ảnh cho nhanh?","a":"<p><strong>Chốt:</strong> Mở S3 Bucket ở chế độ <code>Public Read</code> đồng nghĩa với việc <strong>cho phép cả thế giới đi đường vòng qua lưng CloudFront và AWS WAF để chọc thẳng vào S3.</strong></p>\n<ul>\n <li><strong>1. Vô hiệu hóa hoàn toàn tường lửa WAF và giới hạn tốc độ:</strong> Mọi quy tắc chặn IP độc hại, chặn quốc gia hay <code>Rate-based Rule</code> bạn cài trên <code>CloudFront + AWS WAF</code> đều trở nên vô nghĩa nếu kẻ tấn công gọi thẳng vào địa chỉ <code>bucket-name.s3.amazonaws.com</code>. Chúng có thể tải lặp lại các file lớn trực tiếp từ S3 để đốt cháy hóa đơn băng thông chiều ra (Data Transfer Out) của bạn. </li>\n <li><strong>2. Nguy cơ lộ toàn bộ danh sách file (<code>s3:ListBucket</code>) và dữ liệu người dùng:</strong> Nếu cùng bucket hoặc cấu hình prefix bị lộ quyền đọc công khai, dữ liệu riêng tư của khách hàng có thể bị quét sạch. Với <code>CloudFront OAC</code>, S3 bật <code>Block Public Access = ON</code> tuyệt đối và chỉ chấp nhận các request có chữ ký mật mã học <code>SigV4</code> đến từ đúng <code>Distribution ARN</code> của CloudFront.</li>\n</ul>"},{"q":"Khi phát hiện bản vừa deploy lên Production bị lỗi, tại sao bạn không chạy git revert rồi cho GitHub Actions chạy lại npm run build từ đầu để rollback?","a":"<p><strong>Chốt:</strong> Trong kỹ thuật vận hành Production (SRE), <strong>Rollback không bao giờ được phép phụ thuộc vào việc biên dịch lại mã nguồn (Never Rebuild to Rollback)</strong> vì hai lý do: <strong>Thời gian khôi phục (MTTR)</strong> và <strong>Tính tất định của bản dựng (Build Determinism)</strong>.</p>\n<ul>\n <li> <strong>1. Mất 5–10 phút vàng ngọc khi hệ thống đang cháy: </strong> Khởi tạo máy ảo CI, kéo code, chạy <code>npm ci</code>, <code>npm run build</code> và đồng bộ lại toàn bộ tài sản tốn từ 4 đến 10 phút. Trong khi đó, chép lại file <code>releases/$PREV_VERSION/index.html</code> đã lưu sẵn ra gốc bucket chỉ mất đúng <strong>2 giây </strong> vì các file JS/CSS có mã hash của bản cũ vẫn còn nằm nguyên trên S3! </li>\n <li><strong>2. Rủi ro không build lại được hoặc ra kết quả khác:</strong> Nếu đúng lúc đang khẩn cấp mà kho <code>npm</code> gặp sự cố mạng, một thư viện phụ thuộc vừa rút phiên bản, hoặc biến môi trường trong CI vừa bị ai đó sửa, bước <code>npm run build</code> sẽ thất bại ngay lúc bạn cần cứu hệ thống nhất.</li>\n</ul>"},{"q":"Sau mỗi lần deploy tôi chỉ cần chạy invalidate /* cho CloudFront là mọi người nhận bản mới, vậy tại sao còn phải chia hai chính sách cache làm gì cho phức tạp?","a":"<p><strong>Chốt:</strong> Invalidate hàng loạt không thay được chính sách cache, vì nó không sửa được nguyên nhân và có ba cái giá riêng.</p>\n<ul>\n <li><strong>1. Nó không chạm tới trình duyệt:</strong> invalidate chỉ xoá bản ở các điểm biên của CloudFront. Trình duyệt vẫn giữ <code>index.html</code> theo <code>max-age</code> đã khai, nên người dùng vẫn có thể dùng bản cũ tới hết hạn dù biên đã có bản mới.</li>\n <li><strong>2. Nó xoá luôn thứ đáng được giữ:</strong> dùng <code>/*</code> là xoá cả cache của tệp có hash — những tệp mà nội dung không bao giờ đổi. Lần tải sau, mọi người quay về origin, nên đúng lúc deploy là lúc S3 chịu tải cao nhất.</li>\n <li><strong>3. Nó tốn tiền và tốn thời gian:</strong> invalidate được tính theo số đường dẫn mỗi tháng, và việc lan truyền không tức thời. Trong khi đó, invalidate đúng một đường dẫn <code>/index.html</code> là đủ để mọi người nhận bản mới ngay lần mở trang kế tiếp, còn tệp có hash thì không cần invalidate bao giờ.</li>\n</ul>"}],
  "anchor": "Deploy là đổi con trỏ tới một artifact bất biến, không phải ghi đè tại chỗ.",
  "say30": "Tôi build Vue ra dist rồi đẩy tệp có hash lên bucket private với cache một năm và không xoá bản cũ; index.html đẩy sau cùng với no-cache. CloudFront đọc bucket qua OAC nên không ai gọi thẳng S3 được. Rollback là chép index.html của release cũ ra gốc rồi invalidate, mất vài giây, không build lại. Mỗi bản build là một artifact bất biến, và migration đi trước theo kiểu tương thích ngược.",
  "say90": "[Nêu vấn đề (30s)]: index.html là tệp duy nhất không có hash trong tên, nên nếu nó bị cache cùng chính sách với tệp JS thì trình duyệt dùng bản cũ và trỏ vào tệp mà bước --delete vừa xoá: người dùng thấy màn hình trắng, còn máy đội thì vẫn bình thường. Cùng lúc, build lại cũng không tái tạo đúng bản cũ, vì registry và phiên bản thư viện đã khác.\n\n[Cơ chế (45s)]: Hai chính sách cache cho hai loại tệp: tệp có hash không bao giờ đổi nội dung nên cache một năm và immutable, còn index.html để no-cache để mỗi lần mở trang đều hỏi lại và nhận 304 khi chưa đổi. Thứ tự đẩy quan trọng: asset trước, index sau cùng. Bucket để private, bật Block Public Access và cho CloudFront ký yêu cầu bằng OAC, nên mọi request đều đi qua CloudFront. Migration đi trước theo kiểu tương thích ngược để bản cũ và bản mới cùng chạy.\n\n[Ranh giới (15s)]: Không cứu được tab đang chạy JS cũ gọi vào API đã đổi, và nó bắt bạn giữ artifact cũ cùng một chính sách dọn đúng; đổi lại rollback là vài giây thay vì bốn mươi phút.",
  "body": "<p><strong>Kịch bản Use-case thực chiến trong phỏng vấn:</strong></p><ul><li> <strong>Bài toán gặp phải:</strong> Phát hành bản v2.4 với ba thay đổi trong một lần deploy. Migration đổi tên cột phone thành contact_phone trong khi container cũ vẫn truy vấn phone, gây lỗi 500 hàng loạt. Lệnh sync --delete với cache 24 giờ cho mọi file khiến index.html cũ trỏ tới JS đã xóa, còn bucket public cho phép đọc file upload. </li><li><strong>Cách áp dụng Pattern của bài này để giải:</strong> Khóa public access và gắn OAC cho CloudFront. Tách deploy thành hai bước: tải assets có hash trước, index.html no-cache sau cùng. Migration đi theo Expand-Contract: thêm cột mới, code đọc cả hai, xóa cột cũ ở chu kỳ sau.</li><li><strong>Vì sao chọn cách này:</strong> Mỗi lớp chỉ giải một lỗi. Cache, quyền truy cập và schema là ba cơ chế độc lập nên phải cấu hình riêng cho từng lớp.</li></ul><p><strong>Công thức suy luận nhanh khi bị hỏi xoáy (Dấu hiệu -&gt; Phản xạ):</strong></p><ul><li><strong>Dấu hiệu: tỉ lệ 404 trên assets tăng ngay sau deploy: </strong> index.html cache lâu trỏ tới file đã xóa. Phản xạ: no-cache cho index.html và giữ artifact cũ ít nhất một chu kỳ.</li><li><strong>Dấu hiệu: một URL S3 trực tiếp trả nội dung: </strong> Bucket đang public. Phản xạ: bật Block Public Access và chuyển sang OAC.</li><li><strong>Dấu hiệu: rollback phải sửa tay trên production:</strong> Không có artifact đánh số. Phản xạ: đẩy artifact theo commit SHA và rollback bằng đổi con trỏ.</li></ul>",
  "code": "# ✅ Cách làm chuẩn: artifact bất biến, đẩy theo thứ tự, rollback bằng cách trỏ lại artifact cũ.\n# .github/workflows/deploy.yml (rút gọn)\njobs:\n  deploy:\n    runs-on: ubuntu-latest\n    env:\n      BUCKET: app-bucket\n      DIST_ID: E1EXAMPLE\n    permissions:\n      id-token: write          # OIDC: không lưu access key dài hạn trong GitHub\n      contents: read\n    steps:\n      - uses: actions/checkout@v4\n      - name: Build Vue\n        run: npm ci && npm run build          # ra thư mục dist\n      - name: Gắn version theo commit\n        run: echo \"VERSION=${GITHUB_SHA::12}\" >> \"$GITHUB_ENV\"\n      - uses: aws-actions/configure-aws-credentials@v4\n        with:\n          role-to-assume: ${{ secrets.DEPLOY_ROLE_ARN }}   # role chỉ có quyền deploy\n          aws-region: ap-southeast-1\n      # 1. Assets có hash: chỉ ghi thêm, không xoá. Bản cũ còn cần cho người đang cầm HTML cũ.\n      - name: Upload assets\n        run: aws s3 sync dist/assets s3://$BUCKET/assets --cache-control \"public,max-age=31536000,immutable\"\n      # 2. Lưu index.html của bản này thành artifact đã đánh số.\n      - name: Archive artifact\n        run: aws s3 cp dist/index.html s3://$BUCKET/releases/$VERSION/index.html --cache-control no-cache\n      # 3. Smoke test trên staging trước khi đổi con trỏ.\n      - name: Smoke test\n        run: curl -fsS \"$STAGING_URL/health\" && curl -fsS \"$STAGING_URL/\" | grep -q 'id=\"app\"'\n      # 4. Promote: đổi con trỏ index.html ở gốc bucket. Rollback = chạy lại bước này với VERSION cũ.\n      - name: Promote\n        run: |\n          aws s3 cp s3://$BUCKET/releases/$VERSION/index.html s3://$BUCKET/index.html --cache-control no-cache --content-type \"text/html; charset=utf-8\"\n          aws cloudfront create-invalidation --distribution-id $DIST_ID --paths \"/index.html\"\n\n# ❌ Sai phổ biến: aws s3 sync dist s3://$BUCKET --delete\n# Lệnh này ghi đè index.html trước khi assets mới kịp lên, xoá JS mà HTML đã cache vẫn trỏ tới,\n# và không để lại bản ghi nào để rollback.",
  "codeNote": "<p><strong>Giải phẫu từng khối lệnh trong Mẫu code chuẩn:</strong></p>\n<ul>\n <li><strong><code>permissions: id-token: write</code> + <code>role-to-assume</code> (Xác thực OIDC không dùng khóa tĩnh):</strong> GitHub Actions không lưu trữ cặp khóa <code>AWS_ACCESS_KEY_ID</code> sống dài hạn (tránh rủi ro lộ khóa trên kho mã nguồn), mà dùng giao thức <code>OIDC</code> đổi lấy phiên tạm thời của <code>IAM Role</code> chỉ có quyền deploy.</li>\n <li><strong>Bước 1 - Tải các file có băm nội dung lên trước (<code>aws s3 sync dist/assets... --cache-control \"public,max-age=31536000,immutable\"</code>):</strong> Các file JS/CSS do Vite sinh ra đã mang mã hash trong tên file (ví dụ <code>index-8f3a1b.js</code>), nên nội dung của tên file đó không bao giờ thay đổi. Ta đẩy chúng lên S3 <strong>trước tiên</strong>, gắn bộ nhớ đệm 1 năm (<code>immutable</code>) và <strong>không có cờ <code>--delete</code></strong> để những người dùng đang mở tab chứa bản HTML cũ vẫn tải được các chunk JS của bản cũ.</li>\n <li><strong>Bước 2 &amp; 3 - Lưu trữ bản phát hành bất biến theo <code>releases/$VERSION/index.html</code> + Chạy <code>Smoke Test</code>:</strong> Lưu riêng file <code>index.html</code> của từng commit SHA vào thư mục lịch sử và kiểm tra sức khỏe trên môi trường Staging trước khi chạm vào người dùng thật.</li>\n <li><strong>Bước 4 - Đổi con trỏ nguyên tử (<code>Promote</code>) + <code>--cache-control no-cache</code> + <code>create-invalidation</code>:</strong> Chỉ ở bước cuối cùng khi toàn bộ file JS mới đã nằm sẵn trên S3, ta mới chép đè <code>index.html</code> ở gốc bucket với header <code>no-cache</code> (bắt trình duyệt luôn kiểm tra lại <code>ETag</code> trước khi dùng) và xóa cache trên CloudFront. Nhờ vậy, việc Rollback khi có sự cố chỉ mất đúng 2 giây bằng cách chạy lại lệnh <code>aws s3 cp</code> từ thư mục <code>releases/$OLD_VERSION/index.html</code> mà không phải chờ build lại code.</li>\n</ul>",
  "sayIt": ["Tôi build Vue ra dist, đẩy file có hash lên S3 private với cache một năm, rồi đẩy index.html cuối cùng với no-cache, và CloudFront đọc bucket qua OAC.","Migration đi trước theo kiểu tương thích ngược: thêm cột mới, để code đọc được cả hai dạng, rồi mới xoá cột cũ ở chu kỳ sau, vì trong lúc deploy bản cũ và bản mới cùng chạy.","Chỗ hỏng một là index.html cache lâu trỏ tới JS đã xoá, dấu hiệu là tỉ lệ 404 trên assets tăng ngay sau deploy; cách sửa là no-cache cho index.html và không xoá artifact cũ.","Chỗ hỏng hai là bucket public, dấu hiệu là một URL S3 trực tiếp trả nội dung; cách sửa là OAC và chặn public access ở cấp tài khoản.","Chỗ hỏng ba là rollback không có gì để trỏ về, dấu hiệu là phải sửa tay trên production; cách sửa là artifact đánh số theo commit SHA và rollback bằng cách đổi con trỏ.","Cả ba đều là hệ quả của việc deploy ghi đè tại chỗ, nên tôi giữ mỗi bản là một artifact bất biến và chuyển con trỏ có kiểm chứng bằng smoke test."],
  "qids": ["H07","H08","H13","G15"],
  "refs": ["aws-cloudfront","aws-cloudfront-oac","aws-s3-bpa","pg-transactions"],
}
);
